"""Original C++ teaching units. No book text or extracted exercises are stored here."""
import re
UNITS = []


def program(headers, body, declarations=''):
    return '#include <iostream>\n' + ''.join('#include <'+h+'>\n' for h in headers.split() if h != 'iostream') + declarations + '\nint main() {\n' + body + '\n}\n'


def unit(stage, key, title, standard, prose, code, output, exercise, question, correct, wrong, reasoning, anchor, sources=None):
    """exercise: prompt, exact source replacement, replacement text, stdout, worked reasoning."""
    UNITS.append(dict(stage=stage, **build_unit(key, title, standard, prose, code, output, exercise, question, correct, wrong, reasoning, anchor, sources)))


def build_unit(key, title, standard, prose, code, output, exercise, question, correct, wrong, reasoning, anchor, sources=None):
    prompt, old, new, answer_output, answer = exercise
    edits = old if isinstance(old, list) else [(old, new)] if old else []
    solution = code
    for before, after in edits:
        assert before in solution, key
        solution = solution.replace(before, after)
    if not edits: solution = ''
    for header, token in [('utility','std::move'),('string','std::string'),('stdexcept','std::runtime_error')]:
        if token in code + solution:
            if code and '#include <'+header+'>' not in code: code='#include <'+header+'>\n'+code
            if solution and '#include <'+header+'>' not in solution: solution='#include <'+header+'>\n'+solution
    # '|' separates paragraphs only after sentence punctuation; C++ operators such as |, |= and || stay in the text.
    body = re.split(r'(?<=[.!?)"\'`])\|(?=[^\s|=])', prose)
    assert len(body) == 3, (key, len(body))
    return dict(key=key, title=title, standard=standard, body=body, code=code,
                      expectedStdout=output, challenge=prompt, solution=solution, solutionStdout=answer_output,
                      practiceAnswer=answer, question=question, correct=correct, wrong=wrong, reasoning=reasoning,
                      sourceURL='https://eel.is/c++draft/'+anchor,
                      sourceIDs=sources if sources is not None else [], topics=[key.replace('-', ' ')])


S='01 First programs, types, and expressions'
unit(S,'first-program','From source file to a running program',14,
     'A C++ source file is text. Preprocessing resolves directives, compilation produces object code, and linking resolves definitions from other translation units and libraries. The executable is a separate artifact from the source.|main is the hosted program entry point. Include a header before using the declarations it supplies; std::cout is declared by iostream. A newline changes output, while a semicolon terminates the expression statement.|Use the displayed command in a terminal with a C++ compiler. A missing compiler, a compile error, a linker error, and unexpected program output are different failures; diagnose the stage before changing code.',
     program('', '    std::cout << 21 * 2 << "\\n";'),'42\n',
     ('Print a greeting on one line and the product 6 * 7 on the next.', 'std::cout << 21 * 2 << "\\n";', 'std::cout << "Hello, C++\\n" << 6 * 7 << "\\n";', 'Hello, C++\n42\n', 'Insert two newline characters in the output sequence. The arithmetic remains an integer expression and the stream formats its value.'),
     'Which step resolves a function defined in a different object file?', 'Linking', ['Preprocessing alone','Renaming the source file'], 'The linker combines object files and resolves external definitions. Compilation of one translation unit does not supply missing definitions.', 'lex.phases')
unit(S,'initialization','Initialization establishes a value',14,
     'Initialization happens when an object begins its lifetime. Assignment changes an existing object. int n{} initializes n to zero; an uninitialized automatic int must not be read.|Brace initialization rejects narrowing conversions such as a nonconstant floating value to int. Parentheses and braces have different overload-selection rules, especially for initializer_list constructors.|Initialize every object deliberately. A default constructor may establish a class invariant; zero-filled bytes are not a universal substitute for construction.',
     program('', '    int count{};\n    count = 7;\n    std::cout << count << "\\n";'),'7\n',
     ('Start the counter at three and add four using assignment.', 'int count{};\n    count = 7;', 'int count{3};\n    count = count + 4;', '7\n', 'The first declaration initializes count. The later statement reads the initialized value and assigns the sum.'),
     'What does int count{} do?', 'Initializes count to zero', ['Leaves count indeterminate','Allocates a dynamically sized array'], 'Empty braces value-initialize this scalar. Reading an uninitialized scalar is a separate and potentially invalid operation.', 'dcl.init')
unit(S,'conversions','Conversions can discard information',14,
     'Integer and floating types represent different sets of values. A conversion is not proof that the mathematical value is preserved. An explicit cast documents an operation but does not make an out-of-range conversion safe.|Integer division discards the fractional part toward zero. Convert an operand before division when a floating quotient is intended. Converting the already truncated result cannot recover lost information.|Mixed signed/unsigned arithmetic follows the usual arithmetic conversions. Check representability before changing signedness or narrowing a value.',
     program('', '    std::cout << 7 / 2 << " " << static_cast<double>(7) / 2 << "\\n";'),'3 3.5\n',
     ('Compare integer and floating division for -7 divided by 2.', '7 / 2 << " " << static_cast<double>(7)', '-7 / 2 << " " << static_cast<double>(-7)', '-3 -3.5\n', 'Integer division truncates toward zero, so -7/2 is -3. Casting the numerator before division preserves the fractional part in the floating calculation.'),
     'Why does static_cast<double>(7 / 2) produce 3?', 'Integer division happens before the cast', ['double cannot represent 3.5','The cast changes the division operator'], 'The operand expression has already evaluated to the integer 3. Cast an operand before division.', 'expr.arith.conv')
unit(S,'integer-limits','Integer arithmetic needs range arguments',14,
     'Unsigned arithmetic wraps modulo one more than the largest representable value. Signed overflow has undefined behavior; it is not a portable wrapping mechanism.|numeric_limits describes representable limits. Before computing a nonnegative sum a+b, compare b against max-a, provided the preconditions make that subtraction valid.|A test that happens to print a plausible number after signed overflow has not validated the program. Derive bounds and test values at the boundary.',
     program('limits', '    const unsigned top = std::numeric_limits<unsigned>::max();\n    std::cout << (top + 1u) << "\\n";'),'0\n',
     ('Add an overflow guard for unsigned top + 1 before performing that sum.', 'std::cout << (top + 1u)', 'std::cout << (1u <= std::numeric_limits<unsigned>::max() - top)', '0\n', 'The comparison is false, so the sum would exceed the unsigned range even though unsigned evaluation itself would wrap. A checked arithmetic API should reject rather than wrap when that is its contract.'),
     'Which statement is portable?', 'Unsigned arithmetic wraps; signed overflow is undefined', ['All integer arithmetic saturates','Signed overflow always wraps'], 'The two arithmetic models have different contracts. Optimizers may assume signed overflow does not occur.', 'basic.fundamental')
unit(S,'floating-point','Floating-point answers depend on representation',14,
     'Binary floating-point approximates many decimal fractions. Rounding happens during intermediate operations, so changing the evaluation order can change a computed result.|Compare approximate results using an absolute and relative error budget justified by the problem. A tolerance is not a cure for an unstable algorithm, and NaN needs separate treatment.|Check special values with facilities such as isfinite. Do not use exact equality as a general numerical accuracy test or assume every platform has the same floating representation.',
     program('cmath', '    const double value = 0.1 + 0.2;\n    std::cout << (std::abs(value - 0.3) < 1e-12) << "\\n";'),'1\n',
     ('Check that the computed value is finite as well as near 0.3.', '(std::abs(value - 0.3) < 1e-12)', '(std::isfinite(value) && std::abs(value - 0.3) < 1e-12)', '1\n', 'The finite check makes the acceptance policy explicit. The tolerance applies to this small-scale example, not every numerical workload.'),
     'Is floating-point addition associative for all values?', 'No; intermediate rounding can change the result', ['Yes, because addition is associative over real numbers','Only the final operation rounds'], 'Machine arithmetic approximates real arithmetic. Intermediate rounding invalidates a general associativity assumption.', 'basic.fundamental')
unit(S,'expressions','Separate precedence from evaluation order',14,
     'Precedence determines how an expression groups. It does not generally determine the order in which subexpressions are evaluated. Prefer separate statements when mutations would otherwise interact.|The built-in && and || operators short-circuit. Their right operand is evaluated only when necessary, so a bounds check can guard a later access.|Avoid depending on unsequenced side effects or an unspecified argument evaluation order. Extra parentheses can clarify grouping without establishing sequencing.',
     program('vector', '    std::vector<int> v{4, 8};\n    std::size_t index = 2;\n    std::cout << (index < v.size() && v[index] == 8) << "\\n";'),'0\n',
     ('Check index one using the same guarded expression.', 'index = 2', 'index = 1', '1\n', 'The left operand establishes a valid index before the right operand reads the vector. With index two, the right operand is skipped.'),
     'Why is the access skipped when index equals v.size()?', 'Built-in && short-circuits after a false left operand', ['vector adds a hidden bounds check to operator[]','Parentheses reverse evaluation'], 'Short-circuit evaluation gives the guard its safety. operator[] alone does not check the index.', 'expr.log.and')
unit(S,'enumerations','Use scoped enums for distinct domains',14,
     'A scoped enumeration defines a distinct type whose enumerators remain qualified by the enum name. It avoids many accidental integer conversions and name collisions.|An enum can model a closed set of states, but a cast from an integer does not validate an external value. Parse external input into known enumerators explicitly.|An exhaustive switch communicates the intended state handling. Keep error states visible rather than treating every unknown integer as a valid enum.',
     program('', '    enum class State { idle, running };\n    State s = State::idle;\n    std::cout << (s == State::idle) << "\\n";'),'1\n',
     ('Transition to running and verify the new state.', 'State s = State::idle;\n    std::cout << (s == State::idle)', 'State s = State::running;\n    std::cout << (s == State::running)', '1\n', 'Both operands belong to the same scoped enum. The comparison does not require converting the enum to an integer.'),
     'Does casting arbitrary input to an enum validate that input?', 'No; validate external values explicitly', ['Yes, the cast always throws for unknown values','Yes, every integer names an enumerator'], 'A cast is a conversion, not a parser with domain validation.', 'dcl.enum')
unit(S,'string-values','Strings own characters',14,
     'std::string owns a sequence of char values and manages its storage. Copying a string produces an independently modifiable value. Its size counts char elements, not user-perceived Unicode characters.|Use std::string for owned text and introduce non-owning views only with a valid lifetime. Embedded null characters are representable, but APIs expecting a C string stop at a null terminator.|Check encoding and boundary assumptions when processing external text. A byte position is not automatically a Unicode character boundary.',
     program('string', '    std::string original = "cat";\n    auto copy = original;\n    copy[0] = \'b\';\n    std::cout << original << " " << copy << "\\n";'),'cat bat\n',
     ('Append s to the copy without changing the original.', 'copy[0] = \'b\';', 'copy[0] = \'b\';\n    copy += "s";', 'cat bats\n', 'The two strings own independent values. Append may reallocate the copy; it does not change original.'),
     'What does std::string::size() count?', 'char elements, which may be encoding units', ['Always Unicode grapheme clusters','Only non-null characters'], 'A string is a sequence of its character type. Unicode interpretation requires an encoding-aware layer.', 'basic.string')
unit(S,'vector-values','Vectors manage contiguous sequences',14,
     'std::vector<T> owns a contiguous sequence of T objects. size is the number of constructed elements; capacity describes available storage before another reallocation is needed.|reserve changes capacity, not size. Accessing v[0] after reserving an empty vector is still invalid. Use push_back, emplace_back, or resize to construct elements.|Growth can invalidate pointers, references, and iterators. Do not retain them across operations unless the precise invalidation rules permit it.',
     program('vector', '    std::vector<int> values;\n    values.reserve(8);\n    values.push_back(3);\n    std::cout << values.size() << " " << values.front() << "\\n";'),'1 3\n',
     ('Append a second value and report the last element.', 'std::cout << values.size() << " " << values.front()', 'values.push_back(9);\n    std::cout << values.size() << " " << values.back()', '2 9\n', 'push_back constructs an element and increases size. reserve alone would not make a second element accessible.'),
     'After reserving capacity in an empty vector, what is its size?', 'Zero', ['The reserved capacity','An unspecified positive value'], 'reserve allocates storage without constructing elements or changing size.', 'vector.capacity')
unit(S,'scope-and-const','Scope, lifetime, and const answer different questions',14,
     'Scope controls where a name can be found. Lifetime controls when an object exists. Storage duration describes the storage policy; these concepts do not always coincide.|const prevents modification through that access path. A const reference can observe an object whose owner later changes it through another non-const path.|Avoid returning references to local automatic objects. The name may have gone out of scope because the object itself has already been destroyed.',
     program('', '    int value = 3;\n    const int& observed = value;\n    value = 5;\n    std::cout << observed << "\\n";'),'5\n',
     ('Make observed a value snapshot instead of a reference.', 'const int& observed = value;', 'const int observed = value;', '3\n', 'The copy preserves the earlier integer value. A const reference prevents writes through the reference but still observes later writes through value.'),
     'Does a const reference make the referenced object globally immutable?', 'No; other valid mutable aliases may exist', ['Yes, all aliases become const','Yes, until the reference leaves scope'], 'Const qualification governs access through the qualified path, not every alias to the object.', 'basic.life')

S='02 Control flow, functions, and boundaries'
unit(S,'control-flow','Loops maintain an invariant',14,
     'A loop is easier to reason about when an invariant holds before and after every iteration. For a running total, the sum should equal the processed prefix.|Range-for expresses iteration over an existing range without manual indexing. Use an index when the position is part of the algorithm, and check the range before access.|An empty range executes the body zero times. Choose an initial accumulator that gives the correct empty result and avoid unsigned reverse-loop underflow.',
     program('vector', '    int sum = 0;\n    for (int x : std::vector<int>{2, 3, 5}) sum += x;\n    std::cout << sum << "\\n";'),'10\n',
     ('Sum only even values from the same sequence.', 'sum += x;', 'if (x % 2 == 0) sum += x;', '2\n', 'After each iteration the sum equals the even values in the processed prefix. Empty input still produces zero.'),
     'What should a loop invariant describe?', 'A property preserved across iterations', ['Only the final output','The processor clock frequency'], 'An invariant connects initialization, each iteration, and the postcondition.', 'stmt.iter')
unit(S,'function-contracts','Functions separate a contract from its caller',14,
     'A function specifies parameter types, a result type, and behavior. Declarations make a name available; a definition supplies its body. A non-void function must return a value on every reachable path that requires one.|Passing a small scalar by value gives the function its own parameter object. Updating that parameter does not update the caller variable.|State preconditions and failure behavior. A function called twice should not secretly rely on a previous call unless shared state is part of its documented contract.',
     program('', '    int n = 7;\n    std::cout << doubled(n) << " " << n << "\\n";', 'int doubled(int n) { n *= 2; return n; }\n'),'14 7\n',
     ('Change the function to return the square while leaving the caller value alone.', 'n *= 2;', 'n *= n;', '49 7\n', 'The parameter is a copy. Multiplying it changes the returned value, while the caller still owns its original 7.'),
     'Does modifying an int parameter passed by value modify the caller int?', 'No', ['Always','Only if the names match'], 'The parameter is a separate object initialized from the argument.', 'dcl.fct')
unit(S,'reference-parameters','Reference parameters make mutation visible',14,
     'A T& parameter aliases an existing T. It can express in-place modification, but also introduces aliasing and lifetime requirements. A const T& allows reading without a copy.|Prefer a returned value when there is one natural output. Use a reference parameter when mutation is intentionally part of the API, and document whether input arguments may alias each other.|Never retain a reference parameter beyond the referenced object lifetime. The type alone does not make an asynchronous capture safe.',
     program('', '    int n = 7;\n    increment(n);\n    std::cout << n << "\\n";', 'void increment(int& value) { ++value; }\n'),'8\n',
     ('Make increment a by-value calculation and assign its returned value at the call site.', [('void increment(int& value) { ++value; }', 'int increment(int value) { return value + 1; }'), ('increment(n);', 'n = increment(n);')], '', '8\n', 'The function returns a new value rather than mutating an aliased object. The caller explicitly assigns that value.'),
     'What does an int& parameter bind to?', 'An existing int object', ['An independently copied int','A newly allocated integer every time'], 'The reference parameter aliases the argument. Its lifetime cannot exceed the referenced object lifetime.', 'dcl.ref')
unit(S,'overload-resolution','Overloads are selected from types and conversions',14,
     'An overload set contains declarations with the same name and different parameter lists. Resolution considers viable candidates and ranks conversion sequences; the return type alone cannot distinguish overloads.|An exact match can beat a conversion. Implicit constructors and conversions can make an apparently simple call ambiguous or select an unintended candidate.|Keep overload sets coherent. Use explicit conversions at important boundaries, and test integral, floating, const, and reference arguments that exercise different candidates.',
     program('', '    std::cout << category(3) << " " << category(3.0) << "\\n";', 'const char* category(int) { return "integer"; }\nconst char* category(double) { return "floating"; }\n'),'integer floating\n',
     ('Explicitly convert the first argument to double.', 'category(3)', 'category(static_cast<double>(3))', 'floating floating\n', 'Both arguments now have type double, so the double overload is the exact match.'),
     'Can two functions overload solely by return type?', 'No', ['Yes, for every return type','Only for integer returns'], 'The parameter list must distinguish ordinary function overloads; the expected return type does not solve that conflict.', 'over.match')
unit(S,'recursion','Recursion needs a terminating measure',14,
     'A recursive definition reduces a problem to smaller instances and supplies a base case. Identify a measure that decreases on every recursive call.|Stack depth and numeric range remain practical limits. A mathematically terminating definition can still overflow its result type or exhaust a call stack.|Validate inputs before converting signed values to unsigned recursion parameters. For large inputs, choose an iterative or divide-and-conquer algorithm with explicit resource bounds.',
     program('', '    std::cout << triangular(5) << "\\n";', 'unsigned triangular(unsigned n) { return n == 0 ? 0 : n + triangular(n - 1); }\n'),'15\n',
     ('Replace recursion with a loop that preserves the same result.', 'return n == 0 ? 0 : n + triangular(n - 1);', 'unsigned sum = 0; for (unsigned i = 1; i <= n; ++i) sum += i; return sum;', '15\n', 'The loop accumulates the same finite sequence without recursive stack growth. Its i <= n bound still needs a maximum-n restriction to prevent unsigned increment wrap at the type limit.'),
     'What demonstrates progress toward recursive termination?', 'A well-founded measure decreases on each recursive call', ['The function calls itself','The return type is unsigned'], 'A base case alone is insufficient if recursive calls do not move toward it.', 'stmt.return')
unit(S,'lambda-captures','Lambda captures carry ownership choices',14,
     'A lambda creates a closure object. Value captures store values in the closure; reference captures refer to existing objects. A closure that outlives its references can dangle.|A mutable lambda may modify its captured copies. That does not update the original object. An init-capture can construct closure-owned state, including a moved unique_ptr.|For stored or asynchronous callbacks, identify who owns every capture. Capturing this does not extend the pointed-to object lifetime safely.',
     program('', '    int n = 3;\n    auto next = [n]() mutable { return ++n; };\n    const int result = next();\n    std::cout << result << " " << n << "\\n";'),'4 3\n',
     ('Use an immediate reference-capturing lambda to update n.', '[n]() mutable', '[&n]()', '4 4\n', 'The reference capture aliases the still-live local n in this synchronous example. The separate result declaration completes the mutation before the output statement reads n, including in C++14. Returning or storing the closure beyond n\'s lifetime would require a different ownership design.'),
     'Does a value capture normally update the original variable?', 'No; it stores its own captured value', ['Yes, all captures are references','Only when mutable is present'], 'mutable permits modifying the closure copy; it does not convert that copy into a reference.', 'expr.prim.lambda')
unit(S,'pointer-contracts','Pointers need validity and extent',14,
     'A pointer can identify an object, one-past an array, or no object. Only a valid pointer to a live suitable object may be dereferenced. A non-null check alone cannot establish lifetime or bounds.|Pointer arithmetic is constrained to an array object and its one-past position. A one-past pointer is useful as an endpoint but must not be dereferenced.|Prefer ownership types for owners and bounded interfaces for ranges. A raw pointer by itself does not convey how many elements are available or who releases storage.',
     program('', '    int value = 7;\n    int* p = &value;\n    if (p) *p = 9;\n    std::cout << value << "\\n";'),'9\n',
     ('Represent the absent pointer and keep the guarded write.', 'int* p = &value;', 'int* p = nullptr;', '7\n', 'The null guard skips dereference. The original value remains 7; this tests absence, not the safety of arbitrary non-null addresses.'),
     'Is a non-null pointer necessarily safe to dereference?', 'No; lifetime, type, alignment, and bounds still matter', ['Yes','Only if its address is even'], 'A dangling or otherwise invalid pointer may remain non-null.', 'basic.compound')
unit(S,'array-bounds','Array extent is part of an interface',14,
     'A built-in array has a fixed extent, but many function parameters written with array syntax are adjusted to pointers. The extent is then not carried by that parameter type.|std::array retains its extent in the type and supports normal value semantics. at performs a checked access; operator[] requires a valid index.|Choose a clear invalid-index policy. Bounds checking does not solve dangling lifetime, and unsigned index arithmetic can overflow before an access occurs.',
     program('array stdexcept', '    std::array<int, 3> a{{2, 4, 6}};\n    try { std::cout << a.at(3); } catch (const std::out_of_range&) { std::cout << "bounds\\n"; }'),'bounds\n',
     ('Read the final valid element instead.', 'a.at(3)', 'a.at(2) << "\\n"', '6\n', 'For an extent of three the valid indices are zero, one, and two. at(3) throws rather than returning an element.'),
     'What is the last valid index of a three-element array?', '2', ['3','It depends on capacity'], 'C++ sequences use zero-based indexing; the one-past position is not an element.', 'array')
unit(S,'error-paths','Failure belongs in the function contract',14,
     'A function can report failure with a result value, an exception, or another explicit protocol. Choose a protocol the caller can use correctly and distinguish invalid input from infrastructure failure.|An exception transfers control to a matching handler and destroys fully constructed automatic objects during stack unwinding. Catch by const reference when observing a polymorphic standard exception.|Do not silently replace every failure with a plausible success value. Preserve diagnostics and define which state changes have happened when failure is reported.',
     program('stdexcept', '    try { std::cout << divide(9, 0); } catch (const std::invalid_argument&) { std::cout << "zero\\n"; }', 'int divide(int a, int b) { if (b == 0) throw std::invalid_argument("zero divisor"); return a / b; }\n'),'zero\n',
     ('Exercise the successful path with divisor three.', 'divide(9, 0)', 'divide(9, 3) << "\\n"', '3\n', 'The precondition guard accepts three. A production division helper also needs a policy for the minimum signed integer divided by -1.'),
     'Why catch a standard exception by const reference?', 'To observe it without slicing or copying the exception object', ['To prevent stack unwinding','To ignore the failure'], 'Reference binding preserves dynamic type and avoids an unnecessary copy.', 'except.handle')
unit(S,'stream-state','Parsing must check the stream state',14,
     'Formatted extraction changes both the destination and stream state. Test extraction success before consuming the parsed value. A loop written while (input >> value) naturally handles a valid prefix.|Reaching end-of-file and encountering an invalid token are different conditions. A parser must decide whether a partial valid prefix is acceptable.|clear resets state flags; it does not remove an offending token. Recovery must also consume or otherwise handle invalid input, with a bound on work.',
     program('sstream', '    std::istringstream input("2 3 bad 7");\n    int value = 0, sum = 0;\n    while (input >> value) sum += value;\n    std::cout << sum << " " << input.eof() << "\\n";'),'5 0\n',
     ('Parse the complete valid sequence 2 3 7.', '2 3 bad 7', '2 3 7', '12 1\n', 'The final attempted extraction reaches EOF after summing every valid token. In the original input, bad causes failure before EOF.'),
     'Does clear() by itself consume an invalid token?', 'No', ['Yes, it discards the whole stream','Only for integers'], 'State flags and buffered characters are separate. Recovery must handle both.', 'iostate.flags')

S='03 Ownership, lifetime, and value semantics'
unit(S,'raii','A destructor closes every normal ownership path',14,
     'RAII represents resource ownership with an object whose lifetime controls cleanup. The resource might be memory, a file, a lock, or a foreign handle; choosing the correct release operation is part of the type contract.|Construction must either establish the invariant or fail without leaking partially acquired resources. Already constructed member objects are destroyed if a later constructor step throws.|Keep owning members in RAII types and prefer the rule of zero. A scope exit test should cover success, early return, and exception paths rather than only the happy path.',
     program('stdexcept', '    try { Guard g; throw std::runtime_error("stop"); }\n    catch (const std::runtime_error&) { std::cout << "caught\\n"; }', 'struct Guard { ~Guard() { std::cout << "released\\n"; } };\n'),'released\ncaught\n',
     ('Exercise ordinary scope exit instead of the throwing path.', 'throw std::runtime_error("stop");', 'std::cout << "work\\n";', 'work\nreleased\n', 'The same destructor runs when the object leaves scope normally. The catch block is not entered when nothing throws.'),
     'During unwinding, which local objects are destroyed?', 'Fully constructed automatic objects whose scopes are exited', ['Only objects allocated with new','No objects until the catch finishes'], 'Construction completion determines which automatic objects need destruction.', 'except.ctor', ['hayden'])
unit(S,'unique-ownership','unique_ptr transfers one owning handle',14,
     'unique_ptr models exclusive ownership. Its destructor invokes the associated deleter; moving transfers the handle while copying is disabled.|make_unique constructs an owned object without exposing an intermediate raw owning pointer. A custom deleter is necessary for resources whose release operation is not delete.|A moved-from unique_ptr is empty. Check before dereferencing and never create a second owning smart pointer from the same raw address.',
     program('memory utility', '    auto first = std::make_unique<int>(7);\n    auto second = std::move(first);\n    std::cout << bool(first) << " " << *second << "\\n";'),'0 7\n',
     ('Release the second owner using reset and report both empty states.', 'std::cout << bool(first) << " " << *second', 'second.reset();\n    std::cout << bool(first) << " " << bool(second)', '0 0\n', 'reset destroys the previously owned int and stores an empty handle. Both bool observations are then false.'),
     'What does moving a unique_ptr transfer?', 'Its owning handle and deleter state as specified', ['A second independent ownership claim','The integer bits into stack storage'], 'Exclusive ownership changes hands; two simultaneous owners are not created.', 'unique.ptr', ['hayden'])
unit(S,'shared-and-weak','Break ownership cycles with observing handles',14,
     'shared_ptr extends an object lifetime while owning references remain. weak_ptr observes its control block without keeping the object alive; lock attempts to obtain a temporary owning reference.|Two objects that strongly own each other can remain alive after external owners disappear. A weak edge can express the intended non-owning relationship, but the surrounding ownership design still matters.|Control-block thread safety does not make the pointed-to object thread-safe. Concurrent mutable access to that object needs its own synchronization.',
     program('memory', '    std::weak_ptr<int> observer;\n    { auto owner = std::make_shared<int>(9); observer = owner; std::cout << *observer.lock() << "\\n"; }\n    std::cout << observer.expired() << "\\n";'),'9\n1\n',
     ('Keep another strong owner outside the inner scope.', [('std::weak_ptr<int> observer;', 'std::shared_ptr<int> retained;\n    std::weak_ptr<int> observer;'), ('observer = owner;', 'observer = owner; retained = owner;')], '', '9\n0\n', 'retained owns the value after the inner owner leaves scope, so the weak observer has not expired. The final strong owner releases the value at main exit.'),
     'Does weak_ptr keep the observed object alive?', 'No; lock may acquire ownership if it is still alive', ['Yes, until weak_ptr is destroyed','Yes, but only on the same thread'], 'A weak observer does not increment the strong owner count.', 'util.smartptr.weak', ['hayden'])
unit(S,'rule-of-zero','Let member values implement copy ownership',14,
     'A class whose members already manage their resources often needs no custom destructor or copy/move operations. This rule-of-zero design composes library ownership correctly.|Copying a value should preserve its documented semantics. A vector member copies its elements; a shared_ptr member shares ownership. Those are different choices, not interchangeable implementation details.|If a class directly owns a raw resource, review all special members together. A destructor alone can leave an accidental shallow copy and a double release.',
     program('vector', '    Bag a{{1, 2}};\n    auto b = a;\n    b.values[0] = 9;\n    std::cout << a.values[0] << " " << b.values[0] << "\\n";', 'struct Bag { std::vector<int> values; };\n'),'1 9\n',
     ('Add a third element only to the copied bag and compare sizes.', [('b.values[0] = 9;', 'b.values.push_back(3);'), ('a.values[0] << " " << b.values[0]', 'a.values.size() << " " << b.values.size()')], '', '2 3\n', 'The independent vector copy grows to three elements while a retains its two original elements.'),
     'Why does Bag need no custom destructor here?', 'Its vector member already owns and releases its storage', ['Because vectors never allocate','Because structs cannot have destructors'], 'Ownership is delegated to a value member with the needed special-member behavior.', 'class.copy.ctor', [])
unit(S,'move-semantics','std::move requests a value category',14,
     'std::move is a cast to an rvalue reference type. The selected constructor or assignment operator performs any actual transfer. A const source may select a copy when the available move operation requires a non-const rvalue.|A named rvalue-reference parameter is an lvalue expression inside its function. Use std::move when intentionally consuming it, and use forwarding only for a genuinely deduced forwarding reference.|Do not assume every moved-from object is empty. Use its documented postconditions; standard-library objects are generally valid but unspecified unless a stronger guarantee is stated.',
     program('utility', '    Item a;\n    Item b = std::move(a);\n    (void)b;', 'struct Item { Item() = default; Item(const Item&) { std::cout << "copy\\n"; } Item(Item&&) noexcept { std::cout << "move\\n"; } };\n'),'move\n',
     ('Make the original object const and observe the selected operation.', 'Item a;', 'const Item a;', 'copy\n', 'Moving a const Item produces const Item&&. The non-const move constructor cannot bind it, but the const-reference copy constructor can.'),
     'Does std::move itself move a resource?', 'No; it changes the expression category used in overload resolution', ['Yes, it always transfers bytes','Yes, it always empties the source'], 'The operation selected after the cast determines whether anything is moved.', 'forward', ['hayden'])
unit(S,'forwarding','Forward only a deduced forwarding reference',14,
     'A parameter T&& with deduced, cv-unqualified T can be a forwarding reference. Deduction and reference collapsing preserve whether the caller supplied an lvalue or rvalue.|std::forward<T>(value) restores that deduced category. Unconditionally using std::move would consume lvalue arguments too and change the wrapper contract.|Perfect forwarding still has boundaries, including braced initializer lists and overload sets. A generic wrapper is responsible for exception, lifetime, and return-reference behavior as well as argument categories.',
     program('utility', '    int x = 1;\n    relay(x);\n    relay(2);', 'void sink(int&) { std::cout << "lvalue\\n"; }\nvoid sink(int&&) { std::cout << "rvalue\\n"; }\ntemplate<class T> void relay(T&& x) { sink(std::forward<T>(x)); }\n'),'lvalue\nrvalue\n',
     ('Replace forwarding with an unconditional move and explain the changed contract.', 'std::forward<T>(x)', 'std::move(x)', 'rvalue\nrvalue\n', 'The lvalue call is now treated as consumable. This illustrates why a transparent forwarding wrapper must preserve the deduced category.'),
     'Why use forward<T> rather than move in this wrapper?', 'To preserve the argument category captured by deduction', ['To guarantee a copy','To make every argument an rvalue'], 'Forwarding conditionally casts according to T; moving casts unconditionally.', 'forward')
unit(S,'exception-guarantees','Commit changes after fallible preparation',14,
     'The basic exception guarantee preserves valid invariants and avoids resource leaks. The strong guarantee additionally leaves the observable state unchanged when an operation fails. A no-throw guarantee states that failure does not escape as an exception.|Prepare a replacement in temporary RAII-owned state and commit with an operation whose guarantees are known. Copy-and-swap can implement this pattern when the swap itself is appropriate and nonthrowing.|Do not describe a whole operation as strongly exception-safe merely because it uses a temporary. External side effects, throwing swaps, and partially updated related objects can violate that claim.',
     program('vector stdexcept', '    std::vector<int> current{1};\n    try { auto candidate = current; candidate.push_back(2); throw std::runtime_error("reject"); current.swap(candidate); }\n    catch (const std::runtime_error&) {}\n    std::cout << current.size() << "\\n";'),'1\n',
     ('Commit the prepared vector on the successful path.', 'throw std::runtime_error("reject"); ', '', '2\n', 'The swap now executes after successful preparation. Before the commit, candidate owns the tentative change and current retains the original state.'),
     'What does the strong exception guarantee promise?', 'The operation leaves observable state unchanged when it fails', ['No allocation can fail','Every operation is noexcept'], 'Strong rollback behavior differs from the basic invariant-preservation guarantee.', 'res.on.exception.handling', [])
unit(S,'destruction-order','Members are destroyed in reverse construction order',14,
     'Base classes and members are initialized in a fixed order determined by the class declaration, not by the textual order of a constructor initializer list. Destruction reverses the corresponding construction order.|Put dependencies before the members that depend on them. Do not read an uninitialized member simply because its name appears earlier in an initializer expression.|Destructors should normally not throw. A second exception escaping during stack unwinding terminates the program; resource cleanup needs an explicit failure-reporting strategy when release can fail.',
     program('', '    { Pair pair; }', 'struct Mark { const char* name; ~Mark() { std::cout << name; } };\nstruct Pair { Mark first{"A"}; Mark second{"B"}; ~Pair() { std::cout << "P"; } };\n'),'PBA',
     ('Reverse the declaration order of the two members.', 'Mark first{"A"}; Mark second{"B"};', 'Mark second{"B"}; Mark first{"A"};', 'PAB', 'The Pair destructor body executes first, then members are destroyed in reverse declaration order. The member declaration order, not their names, controls the sequence.'),
     'What controls member initialization order?', 'The member declaration order in the class', ['The initializer-list text order','Alphabetical member names'], 'The language defines initialization order independently of initializer-list ordering.', 'class.base.init')
unit(S,'nonowning-views','Views borrow rather than own',17,
     'string_view describes a character range without owning its storage. Constructing or copying the view does not copy the characters or extend their owner lifetime.|Use views for bounded read-only access while the backing storage is live. Modifying or reallocating the owner can change data or invalidate the view, depending on the operation.|Do not return a view into a local string or retain a view into a temporary. Also remember that a view is not required to be null-terminated.',
     program('string string_view', '    std::string owner = "cat";\n    std::string_view view = owner;\n    owner[0] = \'b\';\n    std::cout << view << "\\n";'),'bat\n',
     ('Take an owning snapshot instead of a view.', 'std::string_view view = owner;', 'std::string view = owner;', 'cat\n', 'The copied string owns an independent character sequence. It does not observe the later mutation of owner.'),
     'Does string_view extend its backing string lifetime?', 'No', ['Yes, through reference counting','Only for local strings'], 'A view stores access information, not ownership.', 'string.view.template')
unit(S,'iterator-invalidation','Mutation can invalidate a saved position',14,
     'Iterator validity is specified per container and operation. A vector reallocation invalidates all element references and iterators; erasing elements has its own narrower invalidation rules.|Use the iterator returned by erase when continuing a traversal. Incrementing an invalidated iterator is not a way to recover the next valid position.|Test empty input, consecutive removals, and removal of the final element. Never demonstrate a dangling iterator by running undefined behavior and treating the output as a stable answer.',
     program('vector', '    std::vector<int> v{1, 2, 4, 5};\n    for (auto it = v.begin(); it != v.end();) { if (*it % 2 == 0) it = v.erase(it); else ++it; }\n    for (int x : v) std::cout << x << " ";'),'1 5 ',
     ('Remove odd values instead, including the final element.', '*it % 2 == 0', '*it % 2 != 0', '2 4 ', 'erase returns the successor or end. Assigning that iterator handles consecutive removals and avoids incrementing an invalidated iterator.'),
     'Which iterator should continue traversal after vector::erase?', 'The iterator returned by erase', ['The erased iterator after incrementing it','A saved end iterator from before every mutation'], 'The returned iterator is the specified continuation point; invalidation rules apply to previously saved positions.', 'vector.modifiers')

S='04 Objects, interfaces, and software design'
unit(S,'class-invariants','Construct only valid domain values',14,
     'A class invariant describes valid observable states. Keep representation private when arbitrary mutation would violate that invariant, and validate at construction or another controlled boundary.|A constructor cannot return an error code, but it can throw; a separate factory may return a result type. Choose an interface that makes invalid states hard to represent.|Check both creation and later mutation. A validating constructor does not protect a public field that callers can overwrite with an invalid value.',
     program('stdexcept', '    Positive p(3);\n    std::cout << p.get() << "\\n";', 'class Positive { int value; public: explicit Positive(int n) : value(n) { if (n <= 0) throw std::invalid_argument("positive required"); } int get() const { return value; } };\n'),'3\n',
     ('Test constructor rejection of zero.', 'Positive p(3);\n    std::cout << p.get() << "\\n";', 'try { Positive p(0); } catch (const std::invalid_argument&) { std::cout << "rejected\\n"; }', 'rejected\n', 'The object is not successfully constructed when validation throws. Its private representation cannot be overwritten through the public API.'),
     'Why keep the representation private in this example?', 'To preserve the positive-value invariant through the API', ['To eliminate all copies','To guarantee thread safety'], 'Access control supports an invariant but does not itself provide synchronization.', 'class', [])
unit(S,'aggregates','Aggregate values expose a simple representation',17,
     'An aggregate can be initialized from its elements without a user-provided construction protocol, subject to the standard version rules. It is useful when every combination of member values is acceptable.|Structured bindings introduce names for elements of an array, tuple-like type, or suitable class. Binding by value copies; binding by reference aliases the original object.|Use an encapsulated class when initialization must enforce relationships among fields. Aggregate convenience does not justify exposing an invalid state.',
     program('', '    Point p{2, 3};\n    auto [x, y] = p;\n    x = 9;\n    std::cout << p.x << " " << x << " " << y << "\\n";', 'struct Point { int x; int y; };\n'),'2 9 3\n',
     ('Bind the decomposition to the original members by reference.', 'auto [x, y] = p;', 'auto& [x, y] = p;', '9 9 3\n', 'The reference decomposition aliases p, so assigning x changes p.x. The value decomposition created separate values.'),
     'What does auto& [x, y] = p allow here?', 'Changing p through the bound member names', ['Changing only detached copies','Extending p forever'], 'The reference qualification changes decomposition ownership and aliasing.', 'dcl.struct.bind')
unit(S,'const-members','Const member functions document access',14,
     'A const member function treats the object through a const-qualified this pointer. It can be called on a const object and should honor the API promise of logical constness.|mutable permits a member to change in const functions, often for caches or synchronization. It is not permission to hide externally surprising state changes or a data race.|Return const access when callers should observe without mutation. A const method returning a mutable pointer to shared state needs particular ownership and synchronization scrutiny.',
     program('', '    const Counter c{4};\n    std::cout << c.get() << "\\n";', 'struct Counter { int value; int get() const { return value; } };\n'),'4\n',
     ('Return twice the stored value without mutating the const object.', 'return value;', 'return 2 * value;', '8\n', 'The calculation uses read-only access. A const method may compute and return a new value without changing the object.'),
     'Can this get() be called on a const Counter?', 'Yes, because get is const-qualified', ['No member function can be called on const objects','Only after const_cast'], 'The const member-function qualifier makes the implicit object parameter suitable for const objects.', 'class.mfct.non.static')
unit(S,'inheritance-and-slicing','Polymorphism requires preserving the dynamic object',14,
     'A derived object contains its base subobject. Copying it into a standalone base value slices away the derived portion. References and pointers can preserve access to the dynamic object.|Virtual dispatch selects the final overrider through a suitable base reference or pointer. Nonvirtual calls follow their static declarations; not every member call is dynamic.|Use inheritance for an intentional substitutability contract. Prefer composition when code reuse alone is the goal, and avoid promising behavior a derived class cannot preserve.',
     program('', '    Derived d;\n    Base sliced = d;\n    const Base& observed = d;\n    std::cout << sliced.name() << " " << observed.name() << "\\n";', 'struct Base { virtual const char* name() const { return "base"; } virtual ~Base() = default; };\nstruct Derived : Base { const char* name() const override { return "derived"; } };\n'),'base derived\n',
     ('Replace the slicing copy with another base reference.', 'Base sliced = d;', 'const Base& sliced = d;', 'derived derived\n', 'Both references now designate the same live Derived object and virtual dispatch selects Derived::name.'),
     'What is lost when a Derived is copied into a Base value?', 'The derived portion of the object', ['The base subobject','The vtable of every object in the program'], 'Object slicing creates a standalone Base value rather than retaining a Derived dynamic object.', 'class.virtual', [])
unit(S,'virtual-destruction','Deletion through an interface needs a release contract',14,
     'Deleting a derived object through a base pointer generally requires a virtual base destructor. An owning polymorphic interface should make that destruction contract explicit.|A protected nonvirtual destructor is another design when clients must not delete through the base. The choice depends on the ownership API, not just whether some other member is virtual.|Use unique_ptr<Base> only when its deleter is correct for the actual dynamic object. An interface declaration is incomplete until construction and destruction responsibilities are clear.',
     program('memory', '    std::unique_ptr<Base> p = std::make_unique<Derived>();', 'struct Base { virtual ~Base() { std::cout << "B"; } };\nstruct Derived : Base { ~Derived() override { std::cout << "D"; } };\n'),'DB',
     ('Release the polymorphic owner explicitly and confirm it is empty.', 'std::unique_ptr<Base> p = std::make_unique<Derived>();', 'std::unique_ptr<Base> p = std::make_unique<Derived>();\n    p.reset();\n    std::cout << bool(p);', 'DB0', 'reset invokes the virtual destruction chain once. Destruction of the now-empty unique_ptr does not release the object a second time.'),
     'Why is the base destructor virtual?', 'To destroy the complete derived object through the owning base pointer', ['To allow any cast','To make construction virtual'], 'The polymorphic release path must match the object actually allocated.', 'class.dtor', ['hayden'])
unit(S,'operator-design','Operators should preserve value expectations',14,
     'An overloaded operator is a function with operator syntax. It does not change precedence or the number of operands, and should preserve the ordinary expectations associated with that operator.|Implement a compound assignment as the mutating primitive and implement addition using a copy when appropriate. Return types and const access are part of the value contract.|Check overflow, unit compatibility, and symmetry where they matter. An elegant spelling does not compensate for an undocumented domain error.',
     program('', '    Length a{2}, b{3};\n    std::cout << (a + b).value << " " << a.value << "\\n";', 'struct Length { int value; Length& operator+=(Length rhs) { value += rhs.value; return *this; } };\nLength operator+(Length lhs, Length rhs) { return lhs += rhs; }\n'),'5 2\n',
     ('Use compound assignment and observe that the left operand changes.', 'std::cout << (a + b).value', 'a += b;\n    std::cout << a.value', '5 5\n', 'operator+= mutates a. operator+ previously mutated a local copy and left a unchanged.'),
     'Can operator overloading change addition precedence?', 'No', ['Yes, by returning a reference','Only for class members'], 'The grammar and precedence remain fixed; overloads change the function called.', 'over.oper', ['learninglad'])
unit(S,'casts-and-rtti','Choose casts by the property being checked',14,
     'static_cast expresses selected compile-time conversions; dynamic_cast checks certain polymorphic conversions at runtime; const_cast changes cv access; reinterpret_cast provides low-level conversions with strict usability limits.|A pointer dynamic_cast that cannot find the requested derived object returns null. A reference form reports failure by throwing bad_cast. Neither repairs a dangling source pointer.|A cast does not create a new object lifetime, validate arbitrary bytes, or make modification of a truly const object legal. Prefer an interface that avoids repeated downcasts.',
     program('', '    Base base;\n    Base* p = &base;\n    std::cout << (dynamic_cast<Derived*>(p) == nullptr) << "\\n";', 'struct Base { virtual ~Base() = default; };\nstruct Derived : Base {};\n'),'1\n',
     ('Point at an actual Derived object and repeat the checked cast.', 'Base base;', 'Derived base;', '0\n', 'The dynamic object now contains the requested Derived type. The cast succeeds while the live object remains in scope.'),
     'What happens when this pointer dynamic_cast cannot find Derived?', 'It returns nullptr', ['It always throws bad_cast','It constructs a Derived'], 'The pointer and reference forms have different failure behavior.', 'expr.dynamic.cast')
unit(S,'type-erasure','Erase representation behind a chosen contract',14,
     'Type erasure stores values of different concrete types behind a common operation set. std::function is a callable example; it owns a callable subject to its type requirements.|An erased wrapper still has ownership, allocation, copying, and exception behavior. It does not erase the need to define those contracts. Reference captures inside the stored callable can still dangle.|Compare inheritance, templates, variants, and type erasure by the extension boundary: whether new types or new operations are expected, and where dependencies should live.',
     program('functional', '    std::function<int(int)> transform = [factor = 3](int x) { return factor * x; };\n    std::cout << transform(4) << "\\n";'),'12\n',
     ('Replace the stored operation while preserving the erased callable signature.', 'std::cout << transform(4)', 'transform = [](int x) { return x + 5; };\n    std::cout << transform(4)', '9\n', 'The wrapper still accepts an int and returns an int, although the concrete lambda type and behavior change.'),
     'What does type erasure hide?', 'Concrete representation behind a selected operation contract', ['Every runtime cost','All captured lifetimes'], 'The public operation set remains visible while concrete implementation types can vary.', 'func.wrap.func', [])
unit(S,'dependency-design','Inject the dependency that varies',14,
     'A strategy parameter lets a stable algorithm delegate a varying policy. Dependency injection makes that policy explicit and can make failure behavior testable without global configuration.|Choose runtime polymorphism when selection changes at runtime and static polymorphism when a compile-time type is appropriate. Neither choice universally minimizes complexity or cost.|Keep the injected interface narrow. A mock that merely mirrors implementation details can hide a broken contract; test visible behavior and meaningful failure paths.',
     program('functional', '    std::cout << price(10, [](int n) { return n / 2; }) << "\\n";', 'int price(int base, const std::function<int(int)>& discount) { return discount(base); }\n'),'5\n',
     ('Inject a fixed two-unit discount instead.', 'return n / 2;', 'return n - 2;', '8\n', 'The pricing algorithm delegates only the discount policy. The client can test each policy independently without changing the pricing function.'),
     'Which dependency should an injected interface expose?', 'The narrow behavior the algorithm actually needs', ['Every method of the production subsystem','Only a global singleton'], 'A small contract reduces coupling and makes alternative implementations easier to reason about.', 'func.wrap', ['hayden'])
unit(S,'object-representation','Bytes are not a portable serialization format',17,
     'sizeof reports object representation size, including padding. Layout, alignment, byte order, and ABI rules may vary across implementations. A trivially copyable object has specific byte-copy guarantees, not a universal wire format.|Use explicit field encoding for persistent or network data. Do not write an arbitrary class representation to disk and assume another compiler or process can reconstruct it safely.|Avoid reading uninitialized padding or violating aliasing and lifetime rules through casts. A byte operation must satisfy the requirements of both the source and destination objects.',
     program('cstring type_traits', '    static_assert(std::is_trivially_copyable<Record>::value, "byte-copy precondition");\n    Record a{7}, b{};\n    std::memcpy(&b, &a, sizeof a);\n    std::cout << b.value << "\\n";', 'struct Record { int value; };\n'),'7\n',
     ('Change the source field while retaining the valid byte-copy precondition.', 'Record a{7}', 'Record a{11}', '11\n', 'Both objects already exist, have the same trivially copyable type, and do not overlap. This local copy still does not define an external serialization format.'),
     'Does trivially copyable imply a portable network encoding?', 'No; representation and platform details still vary', ['Yes, all such types use network byte order','Only when sizeof is four'], 'Object-copy guarantees are different from a specified external data format.', 'basic.types')

S='05 Generic and compile-time programming'
unit(S,'function-templates','Templates generate typed operations',14,
     'A function template describes a family of functions parameterized by types or values. Deduction finds template arguments from call arguments when the rules permit it.|Instantiation checks operations for the selected arguments. Code that works for int may fail for a type without the required comparison or addition operations.|State the semantic requirements as well as the syntax. A comparison operator existing does not prove that it establishes the ordering an algorithm requires.',
     program('string', '    std::cout << larger(3, 7) << " " << larger(std::string("cat"), std::string("dog")) << "\\n";', 'template<class T> T larger(T a, T b) { return a < b ? b : a; }\n'),'7 dog\n',
     ('Make the integer template argument explicit for the numeric call.', 'larger(3, 7)', 'larger<long>(3, 7)', '7 dog\n', 'The explicit argument selects T=long and the int arguments convert to that type. The string call still deduces its own type.'),
     'Does successful template instantiation prove all semantic requirements?', 'No; semantic contracts still need reasoning and tests', ['Yes, compilation proves the algorithm correct','Only for standard-library types'], 'Type checking verifies permitted expressions, not every ordering or mathematical law.', 'temp.fct')
unit(S,'deduction-and-auto','Deduction can copy or preserve a reference',14,
     'auto deduces a type using rules related to template argument deduction. A plain auto variable usually drops a reference from the initializer and stores a value; auto& preserves reference binding.|decltype examines a declared entity or an expression according to its own rules. decltype(auto) can preserve references and therefore propagate dangling references if used carelessly.|Choose value versus reference intentionally in range loops, structured bindings, and return types. An apparently harmless deduction change can alter ownership or mutation.',
     program('', '    int n = 4;\n    auto value = n;\n    auto& alias = n;\n    alias = 8;\n    std::cout << value << " " << n << "\\n";'),'4 8\n',
     ('Make value another alias of n.', 'auto value = n;', 'auto& value = n;', '8 8\n', 'Both deduced reference declarations now alias the same int. Changing alias is observable through value.'),
     'Does plain auto preserve an initializer reference?', 'Usually no; use auto& when reference binding is intended', ['Always','Only for non-const variables'], 'Plain value deduction and reference deduction have different rules.', 'dcl.spec.auto')
unit(S,'specialization','Specialization selects a distinct implementation',14,
     'A primary class template describes a general case. Partial specialization can select a pattern, such as pointer types, and full specialization handles a particular argument list.|Function templates do not support partial specialization; use overloads or another dispatch mechanism. Keep specialization declarations visible where required before instantiation.|Avoid using a specialization to violate the semantic promise of the generic interface. A selected implementation still owes the caller the documented contract.',
     program('', '    std::cout << Category<int>::pointer << " " << Category<int*>::pointer << "\\n";', 'template<class T> struct Category { static constexpr bool pointer = false; };\ntemplate<class T> struct Category<T*> { static constexpr bool pointer = true; };\n'),'0 1\n',
     ('Classify a pointer-to-pointer using the same pattern.', 'Category<int*>::pointer', 'Category<int**>::pointer', '0 1\n', 'The outermost type still matches T*, with T itself equal to int*. Partial specialization matches a type pattern.'),
     'Can a function template be partially specialized?', 'No; use overloads or another dispatch mechanism', ['Yes, exactly like a class template','Only for pointer arguments'], 'Class and function templates have different specialization facilities.', 'temp.spec.partial')
unit(S,'sfinae','Substitution failure can remove an overload',14,
     'SFINAE can remove a template candidate when substitution fails in its immediate context. It is an overload-selection mechanism, not a catch-all handler for errors anywhere in a template body.|enable_if expresses an older constrained-overload technique. C++20 concepts often express the intended requirement more clearly, while C++14 libraries may still need the older form.|Understand where the constraint participates in substitution. A hard error deep inside an instantiated body is not automatically a substitution failure.',
     program('type_traits', '    std::cout << twice(6) << "\\n";', 'template<class T, typename std::enable_if<std::is_integral<T>::value, int>::type = 0> T twice(T x) { return x + x; }\n'),'12\n',
     ('Call the integral overload with a long value.', 'twice(6)', 'twice(9L)', '18\n', 'long satisfies is_integral, so the default template parameter is well-formed and the function remains a candidate.'),
     'Does SFINAE suppress every error in a template body?', 'No; its immediate-context boundaries matter', ['Yes, all template errors disappear','Only when exceptions are enabled'], 'Errors outside the relevant substitution context can remain hard compilation errors.', 'temp.deduct')
unit(S,'variadic-templates','A parameter pack represents a sequence of arguments',14,
     'Variadic templates accept a compile-time sequence of template or function arguments. Pack expansion forms code for each element; it is not a runtime array of erased values.|A recursive implementation needs a base case. sizeof... reports the number of pack elements without evaluating runtime arguments.|Do not infer sequencing or ownership from pack syntax alone. Forwarding each argument and evaluating side effects require a deliberate contract.',
     program('', '    std::cout << sum(1, 2, 3, 4) << "\\n";', 'int sum() { return 0; }\ntemplate<class T, class... Rest> int sum(T first, Rest... rest) { return first + sum(rest...); }\n'),'10\n',
     ('Exercise the empty-pack base case.', 'sum(1, 2, 3, 4)', 'sum()', '0\n', 'The non-template zero-argument overload supplies the identity result and terminates recursion.'),
     'What does sizeof...(Rest) count?', 'The number of elements in the parameter pack', ['The total heap allocation size','The number of runtime calls'], 'The pack length is a compile-time property.', 'temp.variadic')
unit(S,'fold-expressions','Folds make the reduction identity explicit',17,
     'A fold expression reduces a parameter pack with an operator. Association and an explicit initial value determine behavior, especially for empty packs and non-associative operators.|A binary fold with an initial zero gives a simple empty sum. Other operations need an appropriate identity and compatible operand types.|An algebraic-looking fold still uses C++ operator semantics. Signed overflow, overloaded operators, and evaluation order must be considered for the chosen operation.',
     program('', '    std::cout << sum(2, 3, 4) << " " << sum() << "\\n";', 'template<class... T> auto sum(T... values) { return (0 + ... + values); }\n'),'9 0\n',
     ('Change the reduction into a product with identity one.', '(0 + ... + values)', '(1 * ... * values)', '24 1\n', 'One is the multiplication identity. The empty product is one, while the nonempty product is 2*3*4.'),
     'Why supply an identity in this binary fold?', 'It defines the empty-pack result and participates in the reduction', ['To force dynamic dispatch','To allocate the pack'], 'The initial operand is part of both the expression type and its value semantics.', 'expr.prim.fold')
unit(S,'concepts','Constraints express the admissible interface',20,
     'A concept names a compile-time predicate used in constraints. requires-expressions can test expressions, types, and other requirements without executing them.|A constrained overload can communicate its intended domain and participate in overload ordering. Constraint normalization and subsumption follow language rules rather than arbitrary logical equivalence.|Concept satisfaction checks syntax and specified compile-time predicates. It does not mechanically prove every semantic law such as equality preservation or strict weak ordering.',
     program('concepts', '    std::cout << square(5) << "\\n";', 'template<std::integral T> T square(T x) { return x * x; }\n'),'25\n',
     ('Use an unsigned integral argument while retaining the constraint.', 'square(5)', 'square(6u)', '36\n', 'unsigned int satisfies integral. The constraint does not by itself establish that multiplication is in range for every input.'),
     'Does std::integral guarantee that x*x cannot overflow?', 'No; range correctness is a separate contract', ['Yes, for every input','Only when using requires'], 'The type category is checked, but operand bounds still matter.', 'temp.constr')
unit(S,'constexpr','Constant evaluation is a usable execution mode',14,
     'constexpr permits a function to participate in constant evaluation when the invocation satisfies the applicable rules. It does not require every call to be evaluated during translation.|A constant-expression context such as static_assert requires the result at compile time. A runtime argument can still call the same constexpr function at runtime.|Rules expand across standards. Label examples by the minimum standard they actually require and do not infer support from a compiler accepting a newer extension silently.',
     program('', '    constexpr int answer = cube(3);\n    static_assert(answer == 27, "constant calculation");\n    std::cout << answer << "\\n";', 'constexpr int cube(int x) { return x * x * x; }\n'),'27\n',
     ('Check a different constant argument and its result.', 'cube(3);\n    static_assert(answer == 27', 'cube(4);\n    static_assert(answer == 64', '64\n', 'The changed constant still satisfies static_assert. Both the assertion and expected output must agree with the function definition.'),
     'Must every call to a constexpr function run at compile time?', 'No; the call context and arguments matter', ['Yes','Only if the return type is int'], 'constexpr makes eligible evaluation possible; a required constant-expression context demands it.', 'dcl.constexpr')
unit(S,'consteval','Immediate functions require constant evaluation',20,
     'consteval declares an immediate function. Calls that constitute immediate invocations must produce a constant expression, unlike ordinary runtime calls to constexpr functions.|Use an immediate function when a value must be validated or generated during translation. It is not a general replacement for a function that must accept runtime input.|Keep diagnostics and valid input domains explicit. A compile-time result does not make later indexing or arithmetic automatically safe.',
     program('', '    constexpr int n = validated(7);\n    std::cout << n << "\\n";', 'consteval int validated(int n) { if (n < 0) throw "negative"; return n; }\n'),'7\n',
     ('Validate zero as a boundary constant.', 'validated(7)', 'validated(0)', '0\n', 'Zero is accepted by the stated n>=0 contract. A negative constant would fail constant evaluation rather than become a runtime exception in this invocation.'),
     'Which declaration requires immediate invocation rules?', 'consteval', ['mutable','thread_local'], 'consteval and constexpr express different requirements on eligible function calls.', 'dcl.constexpr')
unit(S,'constinit','Static initialization and constness are independent',20,
     'constinit requires a variable with static or thread storage duration to have static initialization. It diagnoses an initialization that would instead require dynamic initialization.|constinit does not make the object const. A mutable constinit variable can change at runtime after its initialization requirement has been satisfied.|Initialization-order reasoning still needs dependency analysis. constinit does not synchronize later concurrent access or replace an atomic or mutex.',
     program('', '    ++counter;\n    std::cout << counter << "\\n";', 'constinit int counter = 4;\n'),'5\n',
     ('Start the statically initialized counter at zero.', 'counter = 4;', 'counter = 0;', '1\n', 'The constant initializer satisfies constinit and the later increment remains permitted because the variable is not const.'),
     'Does constinit imply the variable cannot change?', 'No; it constrains initialization, not later mutability', ['Yes','Only for global variables'], 'Initialization timing and const qualification are independent properties.', 'dcl.constinit')

S='06 Collections, algorithms, and ranges'
unit(S,'sequence-containers','Choose a sequence by operations and invalidation',14,
     'vector, deque, list, and forward_list have different storage and iterator contracts. Contiguity favors vector for many traversals; node-based storage can support other stability requirements but incurs indirection and allocation.|Choose the container from required operations and measured workload, not a slogan about insertion complexity. Finding the insertion position can dominate the advertised insertion cost.|Do not transfer one container invalidation rule to another. Review the exact operation, including end iterators and allocator conditions.',
     program('deque', '    std::deque<int> q{2, 3};\n    q.push_front(1);\n    q.push_back(4);\n    std::cout << q.front() << " " << q.back() << "\\n";'),'1 4\n',
     ('Remove both endpoints and inspect the remaining endpoints.', 'std::cout << q.front()', 'q.pop_front(); q.pop_back();\n    std::cout << q.front()', '2 3\n', 'After removing 1 and 4, the deque contains 2 and 3. The precondition for both pop operations is nonempty input.'),
     'Why can insertion cost alone mislead container selection?', 'Locating the position and cache behavior also matter', ['All containers have identical layout','Node allocation is always free'], 'The whole workload includes search, allocation, locality, and iterator requirements.', 'sequences')
unit(S,'ordered-and-hashed','Lookup containers have different ordering contracts',17,
     'map maintains key ordering according to its comparator, while unordered_map partitions keys using hash and equality. Iteration order in an unordered container is not a portable sorted order.|operator[] can insert a missing key and value-initialize its mapped value. Use find when lookup must not mutate the container; try_emplace separates conditional insertion from later access.|Equivalent keys must satisfy the comparator or hash/equality requirements. A poor or inconsistent policy can break correctness or expected performance.',
     program('map', '    std::map<std::string, int> counts;\n    counts.try_emplace("pear", 2);\n    std::cout << (counts.find("apple") == counts.end()) << " " << counts.size() << "\\n";'),'1 1\n',
     ('Use operator[] for the missing key and observe insertion.', '(counts.find("apple") == counts.end())', 'counts["apple"]', '0 2\n', 'The missing mapped int is value-initialized to zero and the map grows. A lookup that must not insert should use find.'),
     'Can map::operator[] insert a missing key?', 'Yes', ['No, it is always read-only','Only if the mapped value is a pointer'], 'The operation supplies a mapped object for a missing key.', 'associative.reqmts')
unit(S,'ordering-contracts','Comparators must establish a strict weak ordering',14,
     'Sorting and ordered containers require a comparator with semantic ordering properties. less(a,a) must be false, and the induced ordering and equivalence must satisfy their transitivity requirements.|Using <= instead of < violates irreflexivity. A comparator depending on mutable external state can invalidate the data structure ordering after insertion.|Test equal elements, distinct equivalence classes, and boundary values. Floating NaNs require a deliberate policy instead of assuming ordinary numeric comparison orders every input.',
     program('algorithm vector', '    std::vector<int> v{4, 1, 3};\n    std::sort(v.begin(), v.end(), [](int a, int b) { return a > b; });\n    for (int x : v) std::cout << x << " ";'),'4 3 1 ',
     ('Sort ascending using a strict comparator.', 'return a > b;', 'return a < b;', '1 3 4 ', 'Strict greater-than and strict less-than each define an ordering on these integers. Replacing them with a non-strict comparison would violate the comparator contract.'),
     'Why is a <= b unsuitable as the sorting comparator?', 'It reports true when comparing an element with itself', ['It sorts too slowly','It only supports unsigned values'], 'A strict weak ordering must be irreflexive.', 'alg.sorting')
unit(S,'iterator-categories','Algorithms need specific traversal capabilities',14,
     'An iterator category describes supported traversal operations and semantic guarantees. A forward iterator supports multipass traversal; a random-access iterator supports efficient jumps and differences under its contract.|Do not apply random-access assumptions to a list iterator or assume an input iterator can be traversed twice. Concept checks in newer standards make some constraints clearer.|Iterator and sentinel validity depends on the underlying range. A valid iterator type does not guarantee that a particular iterator value is still usable.',
     program('list iterator', '    std::list<int> v{2, 4, 6};\n    auto it = v.begin();\n    std::advance(it, 2);\n    std::cout << *it << "\\n";'),'6\n',
     ('Advance one position and read the middle element.', 'std::advance(it, 2)', 'std::advance(it, 1)', '4\n', 'advance works with this bidirectional iterator by stepping. It does not make list traversal constant-time random access.'),
     'Can a list iterator generally use it + 2?', 'No; it is not a random-access iterator', ['Yes, for every iterator','Only when the list has even size'], 'Use operations supported by the iterator category and remain within valid bounds.', 'iterator.requirements')
unit(S,'algorithm-erase','Separate logical removal from container erasure',14,
     'remove_if moves retained values toward the front and returns the new logical end. It does not shrink the container. The tail still contains objects with unspecified values under the algorithm contract.|The erase-remove idiom erases that tail from a sequence container. C++20 erase_if packages common container-specific removal patterns.|After erasure, observe the container invalidation rules. Do not continue with a saved invalid iterator just because the removal algorithm returned successfully.',
     program('algorithm vector', '    std::vector<int> v{1, 2, 3, 4};\n    auto end = std::remove_if(v.begin(), v.end(), [](int x) { return x % 2 == 0; });\n    v.erase(end, v.end());\n    for (int x : v) std::cout << x << " ";'),'1 3 ',
     ('Retain only the even numbers.', 'return x % 2 == 0;', 'return x % 2 != 0;', '2 4 ', 'The predicate marks elements to remove, not elements to retain. Erasing the returned tail changes vector size.'),
     'Does remove_if itself shrink a vector?', 'No; erase must remove the logical tail', ['Yes','Only if every value is removed'], 'Algorithms operate on iterator ranges without necessarily controlling container size.', 'alg.remove')
unit(S,'ranges-pipelines','Ranges compose lazy traversal operations',20,
     'A view can describe a computation over a range without materializing a new container. filter chooses elements and transform computes values as they are traversed.|Laziness changes when work and side effects happen. A pipeline may depend on live source storage and captured state; constructing the pipeline does not generally perform every transformation.|Understand ownership of each adapted range and callable. Prefer pure transformations for predictable repeated traversal and check whether a view is single-pass or multipass.',
     program('ranges vector', '    std::vector<int> v{1, 2, 3, 4};\n    auto result = v | std::views::filter([](int x) { return x % 2 == 0; }) | std::views::transform([](int x) { return x * x; });\n    for (int x : result) std::cout << x << " ";'),'4 16 ',
     ('Select odd values before squaring.', 'x % 2 == 0', 'x % 2 != 0', '1 9 ', 'The filter controls which source values reach transform. No output vector is required to traverse this pipeline.'),
     'When does this transform compute values?', 'As the view is traversed', ['Always when the pipeline is declared','Only when the vector is destroyed'], 'This view pipeline describes deferred traversal work.', 'range.adaptors')
unit(S,'borrowed-ranges','Borrowing requirements are separate from iterator types',20,
     'A range algorithm may return an iterator whose usefulness depends on the range lifetime. borrowed_range identifies ranges whose iterators can remain usable independently of the range wrapper lifetime under its requirements.|Borrowed status does not keep underlying storage alive. A span wrapper may be temporary while its backing array remains live; an owning temporary vector destroys its elements when it dies.|Store the owner when a returned position must remain usable. Recognize dangling result types instead of forcing a cast around a lifetime error.',
     program('ranges span vector', '    std::cout << std::ranges::borrowed_range<std::span<int>> << " " << std::ranges::borrowed_range<std::vector<int>> << "\\n";'),'1 0\n',
     ('Inspect an lvalue vector range, whose lifetime remains the caller responsibility.', 'borrowed_range<std::vector<int>>', 'borrowed_range<std::vector<int>&>', '1 1\n', 'An lvalue range expression can meet borrowed_range while the program still has to keep the referenced vector alive.'),
     'Does borrowed_range extend the backing storage lifetime?', 'No', ['Yes, through reference counting','Only for spans'], 'The concept describes iterator validity relative to a range wrapper, not automatic ownership.', 'range.range')
unit(S,'pmr-resources','A memory resource must outlive its allocations',17,
     'Polymorphic allocators delegate allocation through a memory_resource interface. PMR lets runtime-selected resource policies serve containers without changing their element type.|A monotonic_buffer_resource releases its accumulated storage together rather than reclaiming each individual deallocation. Its upstream resource can allocate if the supplied buffer is insufficient unless that fallback is deliberately disabled.|Destroy resource-using objects before the resource. Resetting a resource while its containers still use the storage invalidates those objects; stack placement alone does not prove lifetime order.',
     program('memory_resource vector', '    std::byte storage[1024];\n    std::pmr::monotonic_buffer_resource arena(storage, sizeof storage, std::pmr::null_memory_resource());\n    std::pmr::vector<int> v(&arena);\n    v.push_back(7);\n    std::cout << v.front() << "\\n";'),'7\n',
     ('Store two integers and report the container size.', 'v.push_back(7);\n    std::cout << v.front()', 'v.push_back(7); v.push_back(9);\n    std::cout << v.size()', '2\n', 'The vector is declared after the arena, so it is destroyed first. null_memory_resource makes exhaustion throw rather than silently allocate from a heap resource.'),
     'What must outlive a PMR container that uses its storage?', 'The supplying memory resource', ['Only the allocator variable name','Nothing, because PMR copies the arena'], 'Allocator indirection does not transfer ownership of the resource.', 'mem.res', [])
unit(S,'span','Span adds extent without ownership',20,
     'span<T> pairs access to contiguous elements with an extent. It can use a static or dynamic extent but does not allocate or own the elements.|A span can be a safer interface than unrelated pointer and length parameters, yet operator[] still requires a valid index. The backing storage must stay live and suitably stable.|Use const element access when mutation is not intended. Constness of the span wrapper itself differs from constness of the elements it views.',
     program('span array', '    std::array<int, 3> a{1, 2, 3};\n    std::span<int> view(a);\n    view[1] = 9;\n    std::cout << a[1] << " " << view.size() << "\\n";'),'9 3\n',
     ('Use a span subrange to modify the final element.', 'view[1] = 9;', 'auto tail = view.subspan(2);\n    tail[0] = 7;', '2 3\n', 'The final array element becomes 7 while a[1] remains 2. subspan changes the viewed range and does not change the original span extent.'),
     'Does a span own the elements it references?', 'No', ['Yes, it frees them at destruction','Only for static extent'], 'Extent information and ownership are separate responsibilities.', 'views.span')
unit(S,'numeric-algorithms','Reduction order affects admissible operations',17,
     'accumulate evaluates a left fold in its specified order. reduce permits regrouping and reordering under its contract, which supports parallel implementations but changes what results can be assumed.|Integer addition within range works well for this demonstration. Floating addition and non-associative operations require more careful expectations.|Do not assume a parallel execution policy creates threads or speeds up every workload. Backend support, input size, synchronization, and exceptions affect the behavior.',
     program('numeric vector', '    std::vector<int> v{1, 2, 3};\n    std::cout << std::accumulate(v.begin(), v.end(), 10) << "\\n";'),'16\n',
     ('Use a wider zero accumulator and report the sum.', 'std::accumulate(v.begin(), v.end(), 10)', 'std::accumulate(v.begin(), v.end(), 0LL)', '6\n', 'The initial value participates in both accumulator type and result. A wider accumulator can avoid overflow for a bounded input range, but is not an unlimited integer.'),
     'Can reduce generally regroup operations unlike accumulate?', 'Yes, subject to its requirements', ['No, both specify the same left-to-right fold','Only for strings'], 'Algorithms with different evaluation-order contracts can yield different floating results.', 'numeric.ops')

S='07 Standard-library vocabulary and systems facilities'
unit(S,'optional','Optional distinguishes absence from a value',17,
     'optional<T> represents either no value or an owned T. Absence is not the same as an arbitrary sentinel such as zero, which may be valid data.|Check engagement before dereference. value() throws bad_optional_access for an empty optional; operator* requires engagement. value_or supplies a fallback value.|Optional describes absence but carries no error reason. Use a richer result representation when callers need to distinguish multiple failure cases.',
     program('optional', '    std::optional<int> found;\n    std::cout << found.value_or(9) << "\\n";'),'9\n',
     ('Store zero as an engaged result and distinguish it from absence.', 'std::optional<int> found;', 'std::optional<int> found = 0;', '0\n', 'Zero is a real contained int. value_or returns it instead of the fallback because the optional is engaged.'),
     'Does an optional containing zero count as empty?', 'No', ['Yes','Only when converted to bool'], 'Engagement is distinct from the contained value.', 'optional')
unit(S,'variant','Variant models a closed set of alternatives',17,
     'variant<T...> holds one active alternative from a fixed set. visit applies an operation compatible with the alternatives instead of manually guessing the stored representation.|Use get_if for checked pointer access to a selected alternative. get throws when the requested alternative is not active; exception behavior can also leave a variant valueless under specified circumstances.|Choose variants when the type set is closed and new operations are common. An open plugin type set may call for a different extension boundary.',
     program('variant string', '    std::variant<int, std::string> value = 7;\n    std::visit([](const auto& x) { std::cout << x << "\\n"; }, value);'),'7\n',
     ('Activate the string alternative and reuse the visitor.', 'value = 7;', 'value = std::string("ready");', 'ready\n', 'The same generic visitor supports both alternative types. The active alternative changes with assignment.'),
     'What does a variant define at compile time?', 'A closed set of possible alternative types', ['Every possible plugin type','An untyped byte buffer with no active member'], 'The listed alternatives are part of the variant type.', 'variant', [])
unit(S,'any','Any preserves a checked concrete type',17,
     'any owns a value with a concrete type erased from its public type. any_cast requests the stored type; it does not perform arbitrary numeric conversion.|The pointer form of any_cast returns null for a type mismatch. The value/reference forms can throw bad_any_cast. Know which failure protocol your API selects.|Use a typed variant or dedicated interface when the admissible values and operations are known. Erasure should serve an extension requirement rather than avoid designing a contract.',
     program('any', '    std::any value = 7;\n    std::cout << (std::any_cast<double>(&value) == nullptr) << " " << *std::any_cast<int>(&value) << "\\n";'),'1 7\n',
     ('Store a double and observe that the checked int lookup fails instead.', [('value = 7;', 'value = 3.5;'), ('(std::any_cast<double>(&value) == nullptr) << " " << *std::any_cast<int>(&value)', '(std::any_cast<int>(&value) == nullptr) << " " << *std::any_cast<double>(&value)')], '', '1 3.5\n', 'The requested concrete type must match. any_cast does not reinterpret the int as a double or convert a double to int.'),
     'Does any_cast<double> convert a stored int to double?', 'No; it checks the stored concrete type', ['Yes, like static_cast','Only for positive numbers'], 'Type erasure preserves runtime type identity rather than enabling every conversion.', 'any')
unit(S,'expected','Expected carries either success or a specific error',23,
     'expected<T,E> holds either a successful T or an error E. It makes an error value part of the result type and is useful when the caller should handle ordinary failures explicitly.|Check has_value or the boolean state before accessing the successful value. error() requires the error alternative; these are contracts rather than automatic validation of every access.|Choose an error type with useful domain information. Do not replace every exception with an undifferentiated string when callers need structured recovery.',
     program('expected string', '    auto result = parse(false);\n    std::cout << (result ? std::to_string(*result) : result.error()) << "\\n";', 'std::expected<int, std::string> parse(bool valid) { if (!valid) return std::unexpected(std::string("invalid")); return 7; }\n'),'invalid\n',
     ('Exercise the successful branch using the same result interface.', 'parse(false)', 'parse(true)', '7\n', 'The boolean branch protects access to the correct alternative. The successful value and error reason remain distinct types.'),
     'What additional information can expected carry compared with optional?', 'A typed error value', ['A guarantee of no allocations','Automatic retries'], 'optional models presence; expected adds a separate error alternative.', 'expected')
unit(S,'tuple-binding','Tuples package heterogeneous values',17,
     'tuple holds a fixed sequence of potentially different types. Structured bindings can give those positions meaningful local names; a named domain struct is often clearer at public API boundaries.|tie forms references to existing variables, while make_tuple normally stores values after its specified decay rules. Reference wrappers and forwarding tuples have additional lifetime considerations.|Do not return a tuple of references to locals. Packaging references together does not change the lifetime of any referenced object.',
     program('tuple string', '    auto record = std::make_tuple(std::string("Ada"), 3);\n    auto [name, count] = record;\n    std::cout << name << " " << count << "\\n";'),'Ada 3\n',
     ('Change the second tuple value before decomposing it.', 'auto [name, count] = record;', 'std::get<1>(record) = 5;\n    auto [name, count] = record;', 'Ada 5\n', 'get uses a compile-time position here. The later value decomposition copies the updated tuple values.'),
     'Does a tuple containing references own the referenced objects?', 'No', ['Always','Only when returned from a function'], 'A reference remains non-owning regardless of the enclosing tuple.', 'tuple')
unit(S,'filesystem','Filesystem paths have lexical and external meanings',17,
     'filesystem::path represents a path using platform-specific rules. Lexical transformations manipulate path components without proving anything about the actual filesystem.|Filesystem operations can fail because of permissions, races, missing entries, or changing external state. Many operations offer throwing and error_code forms with different handling protocols.|Do not treat lexical normalization as a security sandbox. Symlinks and time-of-check/time-of-use races require a stronger file-access design.',
     program('filesystem', '    std::filesystem::path path = "reports/../data/file.txt";\n    std::cout << path.lexically_normal().generic_string() << "\\n";'),'data/file.txt\n',
     ('Report the extension without accessing the filesystem.', 'path.lexically_normal().generic_string()', 'path.extension().generic_string()', '.txt\n', 'extension is a lexical query on the path representation. It does not prove that the named file exists.'),
     'Does lexically_normal resolve symlinks on disk?', 'No; it is a lexical operation', ['Yes','Only for relative paths'], 'Lexical normalization and filesystem resolution are different operations.', 'filesys')
unit(S,'formatting','Formatting makes the output contract visible',20,
     'format constructs a formatted string using a format specification and typed arguments. It separates formatting intent from persistent stream flags.|Language mode alone does not prove the standard library supplies a particular formatting feature. Check library feature macros and compile the actual example on the recorded implementation.|Formatting can allocate and can report errors. Validate untrusted format strings according to the chosen API and keep diagnostic output separate from machine-readable data.',
     program('format', '    std::cout << std::format("{:04}", 7) << "\\n";'),'0007\n',
     ('Format the integer as two-digit hexadecimal.', 'std::format("{:04}", 7)', 'std::format("{:02x}", 31)', '1f\n', 'The format specification chooses width, zero fill, and hexadecimal representation. It does not mutate later stream formatting state.'),
     'Does selecting -std=c++20 prove every library feature is implemented?', 'No; compiler and library support must both be checked', ['Yes','Only for formatting'], 'The language dialect and available standard-library implementation are separate parts of the toolchain.', 'format')
unit(S,'chrono','Durations carry units in their types',14,
     'chrono::duration combines a representation with a tick period. Arithmetic can preserve units and avoid mixing raw milliseconds and seconds accidentally.|duration_cast performs an explicit duration conversion, which may truncate when converting to a coarser integral unit. system_clock and steady_clock serve different purposes: civil timestamps versus monotonic elapsed measurements.|Choose a clock based on the contract. A timeout should normally use a monotonic clock; wall-clock adjustments can otherwise alter elapsed-time decisions.',
     program('chrono', '    auto delay = std::chrono::milliseconds(1500);\n    std::cout << std::chrono::duration_cast<std::chrono::seconds>(delay).count() << "\\n";'),'1\n',
     ('Keep millisecond precision when inspecting the duration.', 'std::chrono::duration_cast<std::chrono::seconds>(delay)', 'std::chrono::duration_cast<std::chrono::milliseconds>(delay)', '1500\n', 'The finer unit preserves the original count. The seconds conversion truncates the half-second fraction.'),
     'Which clock is intended for monotonic elapsed-time measurement?', 'steady_clock', ['A wall-clock string','system_clock with no further assumptions'], 'steady_clock is monotonic under its specified contract.', 'time')
unit(S,'randomness','Random engines and distributions are different layers',14,
     'A pseudorandom engine produces a deterministic state sequence from a seed. A distribution maps engine results into a requested statistical distribution.|A fixed engine seed can make tests reproducible, but distribution algorithms need not produce identical sequences across all standard-library implementations. Test invariants rather than a guessed cross-platform sequence.|Do not use a general simulation engine for cryptographic secrets. Seeding and statistical quality are distinct from security requirements.',
     program('random', '    std::mt19937 engine(7);\n    std::uniform_int_distribution<int> die(1, 6);\n    bool valid = true;\n    for (int i = 0; i < 100; ++i) { int n = die(engine); valid = valid && n >= 1 && n <= 6; }\n    std::cout << valid << "\\n";'),'1\n',
     ('Test the degenerate distribution whose only possible value is four.', [('die(1, 6)', 'die(4, 4)'), ('n >= 1 && n <= 6', 'n == 4')], '', '1\n', 'The valid range has one element. This is a boundary-property test rather than a dependency on an implementation-specific generated sequence.'),
     'Does a fixed seed guarantee the same distribution sequence across all libraries?', 'No; distribution algorithms can differ', ['Yes, every distribution algorithm is fixed','Only when the seed is zero'], 'Engine and distribution portability contracts differ.', 'rand')
unit(S,'bit-utilities','Bit operations describe representation-level intent',20,
     'The bit header offers operations such as popcount, rotations, bit_width, and bit_cast under their stated type requirements. Prefer a named operation over hand-coded shifts with hidden edge cases.|Shift counts and operand types matter. Shifting by a count outside the permitted range is invalid; signed arithmetic and promotion can introduce additional traps.|bit_cast copies object representations under strict constraints. It is not a general serialization or pointer-lifetime escape hatch.',
     program('bit', '    unsigned n = 0b101100u;\n    std::cout << std::popcount(n) << " " << std::bit_width(n) << "\\n";'),'3 6\n',
     ('Test the zero-input boundary.', 'n = 0b101100u', 'n = 0u', '0 0\n', 'Zero has no set bits and needs zero significant binary digits under bit_width. Named utilities avoid special-case shift loops.'),
     'Is a shift by the operand type width generally valid?', 'No', ['Always','Only for zero values'], 'The shift-count precondition must be satisfied even when a particular machine masks shift counts.', 'bit')
unit(S,'regex','Regular expressions have parsing and resource costs',14,
     'regex describes a pattern in a selected grammar. regex_match checks the entire input, while regex_search can find a matching subsequence.|Pattern construction can fail with regex_error. Some patterns and implementations can require substantial time or memory; input limits remain part of a robust parser contract.|For simple structured numeric input, a direct parser may offer clearer diagnostics and resource bounds. Escaping exists at both the C++ string and regular-expression layers.',
     program('regex string', '    const std::regex digits("[0-9]+");\n    std::cout << std::regex_match(std::string("123x"), digits) << " " << std::regex_search(std::string("123x"), digits) << "\\n";'),'0 1\n',
     ('Use an input whose entire contents match.', '123x', '123', '1 1\n', 'Both algorithms succeed when the entire input consists of digits. The original trailing x makes whole-input matching fail.'),
     'Which operation requires the whole input to match?', 'regex_match', ['regex_search','Both always require it'], 'Search and whole-input matching answer different parsing questions.', 're')
unit(S,'system-errors','Error codes include a category',14,
     'error_code pairs an integer with an error_category. The integer alone is not a universal error identity; categories give it meaning and provide comparisons with portable error conditions.|Use error_code overloads when an API offers a useful nonthrowing error-reporting path. This does not mean every surrounding allocation or operation is guaranteed not to throw.|Do not test platform-specific message strings as a correctness oracle. Prefer documented conditions and retain the category and numeric code in diagnostics.',
     program('system_error', '    auto error = std::make_error_code(std::errc::permission_denied);\n    std::cout << (error == std::errc::permission_denied) << "\\n";'),'1\n',
     ('Compare a different standard error condition.', 'error == std::errc::permission_denied', 'error == std::errc::no_such_file_or_directory', '0\n', 'The condition comparison distinguishes two failure categories without relying on localized message text.'),
     'What gives an error_code integer its interpretation?', 'Its error category', ['The variable name','The current source filename'], 'A numeric value is meaningful only within its category contract.', 'syserr')

unit(S,'mdspan','Multidimensional views separate layout from ownership',23,
     'mdspan maps multidimensional indices onto storage through an extent, layout, and accessor policy. It is a non-owning view, so the element storage and resource lifetime remain the caller responsibility.|A layout policy controls how indices map to offsets. Row-major layout_right makes the rightmost index vary fastest; other layouts and strides express different memory organizations.|Validate extents, required storage size, and indices. Constructing a view does not allocate its backing elements or make out-of-range access safe.',
     program('mdspan array', '    std::array<int, 6> data{1, 2, 3, 4, 5, 6};\n    std::mdspan<int, std::extents<std::size_t, 2, 3>> matrix(data.data());\n    std::cout << matrix[1, 2] << "\\n";'),'6\n',
     ('Read the first element of the second row.', 'matrix[1, 2]', 'matrix[1, 0]', '4\n', 'layout_right maps row one, column zero to offset three for these extents. The array remains the owner.'),
     'Does mdspan allocate its backing multidimensional array?', 'No', ['Yes, on every access','Only for static extents'], 'The mapping and accessor describe access to separately owned storage.', 'mdspan')
unit(S,'printing','Print directly with a format contract',23,
     'print and println write formatted output through standard-library facilities. println adds a newline while print does not; format produces a string rather than writing it.|The library implementation must provide the print facilities in addition to the compiler accepting C++23 syntax. The validation records compile and link the actual calls.|Output can fail. Command-line tools need a documented policy for failures, including broken pipes and separate diagnostic streams, rather than assuming printing always succeeds.',
     program('print', '    std::println("value={}", 7);'),'value=7\n',
     ('Print a hexadecimal value with the same labelled output.', 'std::println("value={}", 7)', 'std::println("value={:x}", 31)', 'value=1f\n', 'The format specification selects hexadecimal while println supplies the terminating newline.'),
     'Which operation adds a terminating newline?', 'println', ['print always does','format always writes a newline to stdout'], 'Formatting a string and writing output are separate operations.', 'print')
unit(S,'source-location','Diagnostics can capture the caller location',20,
     'source_location carries information about a source location without requiring callers to spell file and line macros at every call site. A default parameter using current() captures the relevant call location.|File paths, function names, and line numbers are implementation and build dependent. Avoid treating their exact text as a portable output contract.|Keep diagnostic metadata out of secrets and user documents when unnecessary. A useful assertion includes the violated condition and operation context, not just a line number.',
     program('source_location', '    std::cout << has_location() << "\\n";', 'bool has_location(std::source_location where = std::source_location::current()) { return where.line() > 0; }\n'),'1\n',
     ('Also verify that a file name was supplied without asserting its exact path.', 'return where.line() > 0;', 'return where.line() > 0 && where.file_name()[0] != \'\\0\';', '1\n', 'The test checks a property of this compiled diagnostic metadata while avoiding a brittle absolute-path expectation.'),
     'Should a portable test assert the exact build-machine file path?', 'No', ['Yes, every toolchain uses the same path','Only for header functions'], 'The build environment can change source-location strings.', 'support.srcloc')
unit(S,'three-way-comparison','Comparison categories encode different ordering strength',20,
     'The spaceship operator can synthesize comparison behavior and returns an ordering category. Strong, weak, and partial ordering encode different guarantees.|Floating-point comparison can be unordered for NaN, so partial_ordering is materially different from a total ordering. A defaulted comparison compares relevant subobjects under its rules.|Define equality and ordering consistently with the domain. Do not choose a stronger category merely to satisfy an algorithm that actually requires a better comparison policy.',
     program('compare', '    Point a{1, 2}, b{1, 3};\n    std::cout << (a < b) << " " << (a == b) << "\\n";', 'struct Point { int x, y; auto operator<=>(const Point&) const = default; };\n'),'1 0\n',
     ('Compare equal domain values.', 'b{1, 3}', 'b{1, 2}', '0 1\n', 'The defaulted comparison first compares x and then y. Equal member values yield equality rather than less-than.'),
     'Which category can express an unordered comparison?', 'partial_ordering', ['strong_ordering','A bool by itself identifies every category'], 'NaN is a common reason an ordinary floating comparison is unordered.', 'cmp')
unit(S,'locale-and-characters','Character classification requires valid inputs',14,
     'C character classification functions take EOF or a value representable as unsigned char. Passing a negative signed char directly can violate that precondition.|Classification and case conversion can be locale sensitive. A byte-oriented classification routine does not decode a Unicode grapheme or normalize text.|Convert through unsigned char for byte input and choose an explicit encoding policy for real text. Test non-ASCII and invalid sequences at the layer that actually interprets them.',
     program('cctype string', '    std::string s = "a3";\n    int digits = 0;\n    for (unsigned char c : s) if (std::isdigit(c)) ++digits;\n    std::cout << digits << "\\n";'),'1\n',
     ('Count uppercase ASCII characters in the literal A3 instead.', [('s = "a3"', 's = "A3"'), ('std::isdigit(c)', 'std::isupper(c)')], '', '1\n', 'The range variable supplies a representable unsigned-char value to classification. This example classifies the literal bytes, not Unicode text.'),
     'Why convert a possibly signed char before calling isdigit?', 'To satisfy its unsigned-char-or-EOF input precondition', ['To decode UTF-8 automatically','To make every character a digit'], 'Integer promotion of a negative signed char is not a valid general classification argument.', 'cctype.syn')
unit(S,'binary-encoding','Encode fields rather than native object bytes',14,
     'A binary protocol must specify byte order, field widths, lengths, and invalid-input handling. A native integer representation is not automatically the protocol representation.|Decode using unsigned arithmetic with validated widths and bounds. Check the required bytes before reading them, and validate lengths before allocating or computing offsets.|Raw struct dumps can contain padding, native endianness, and nonportable representation. Historical networking material should be paired with current protocol specifications and tested byte-level examples.',
     program('array cstdint', '    std::array<std::uint8_t, 2> bytes{{0x12, 0x34}};\n    unsigned value = (unsigned(bytes[0]) << 8) | unsigned(bytes[1]);\n    std::cout << value << "\\n";'),'4660\n',
     ('Decode the network-order representation of 256.', 'bytes{{0x12, 0x34}}', 'bytes{{0x01, 0x00}}', '256\n', 'The first octet supplies the high eight bits. Unsigned promotion avoids unintended signed shifts in this bounded two-byte decoder.'),
     'Does writing sizeof(struct) bytes define a portable network format?', 'No', ['Yes, if compilation succeeds','Only on a fast processor'], 'A wire protocol requires an explicit representation contract.', 'basic.types', [])
unit(S,'from-chars','Parse numbers without accepting an unnoticed suffix',17,
     'from_chars parses a bounded character range and reports both an error code and the position where parsing stopped. It avoids locale-dependent formatted-stream behavior for its supported conversions.|A successful conversion can still leave a suffix. A whole-token parser must require both success and ptr==last, and must distinguish out-of-range input from invalid syntax.|Define whitespace, sign, base, and empty-input policies. The parser API does not decide the application grammar for you.',
     program('charconv string system_error', '    std::string text = "42x"; int value = 0;\n    auto result = std::from_chars(text.data(), text.data() + text.size(), value);\n    std::cout << (result.ec == std::errc{} && result.ptr == text.data() + text.size()) << "\\n";'),'0\n',
     ('Accept the complete token 42 while rejecting a suffix.', 'text = "42x"', 'text = "42"', '1\n', 'The success error code alone is not enough for the original token. The end-pointer check enforces whole-input consumption.'),
     'Is a successful from_chars error code enough to require whole-token parsing?', 'No; also check the returned pointer reaches the end', ['Yes','Only for hexadecimal values'], 'The returned stopping position is part of the parsing result.', 'charconv', [])

S='08 Concurrency, synchronization, and coroutines'
C=['hayden']
unit(S,'thread-ownership','Join threads before their dependencies disappear',14,
     'A thread handle and the thread it represents have separate lifetimes. A joinable std::thread must be joined or detached before its destructor; otherwise the program terminates.|Joining waits for completion and establishes synchronization with the joined thread. The referenced objects must remain live while the thread can access them.|Detaching does not solve ownership. It removes the join handle while leaving the execution and its dependency lifetimes to another design.',
     program('thread', '    int value = 0;\n    std::thread worker([&] { value = 7; });\n    worker.join();\n    std::cout << value << "\\n";'),'7\n',
     ('Give the worker an owned input value while keeping the output live until join.', 'std::thread worker([&] { value = 7; });', 'std::thread worker([&value, input = 9] { value = input; });', '9\n', 'The closure owns its input copy and borrows value, whose lifetime extends through join. The read occurs only after synchronization.'),
     'Does detach extend the lifetimes of objects captured by reference?', 'No', ['Yes','Only for stack objects'], 'Detached execution still needs valid dependencies.', 'thread.thread', C)
unit(S,'jthread-stop','jthread joins, while stop remains cooperative',20,
     'jthread requests stop and joins during its destruction when joinable. A stop token is a cooperative signal; it does not forcibly interrupt arbitrary blocking operations.|A worker must observe stop or another shutdown condition and make progress toward returning. A blocked wait needs a wakeup design, not merely a boolean nobody checks.|Avoid a worker owning the final controller whose destructor would join that same worker. Define external ownership and teardown order explicitly.',
     program('thread stop_token', '    std::stop_source source;\n    source.request_stop();\n    std::jthread worker([token = source.get_token()] { std::cout << token.stop_requested() << "\\n"; });'),'1\n',
     ('Observe a token whose source has not requested stop.', 'source.request_stop();', '/* no stop requested */', '0\n', 'The lambda observes the explicitly captured token. jthread owns a separate internal stop source unless its own token is passed to the callable.'),
     'Does request_stop forcibly interrupt every blocking call?', 'No; cancellation is cooperative', ['Yes','Only for file I/O'], 'The worker and its wait operations must participate in cancellation.', 'thread.jthread.class', C)
unit(S,'mutex-invariants','Protect the whole shared invariant',14,
     'A mutex gives mutually exclusive access when every relevant access follows the same locking discipline. Protect related state transitions together instead of locking individual fields independently.|lock_guard releases its mutex through RAII. Keep critical sections short and avoid calling unknown user code while holding a lock unless that is an explicit contract.|A mutex does not repair accesses performed outside the discipline. Establish a consistent lock order when more than one mutex can be acquired.',
     program('thread mutex', '    std::mutex mutex; int count = 0;\n    auto work = [&] { for (int i = 0; i < 1000; ++i) { std::lock_guard<std::mutex> lock(mutex); ++count; } };\n    std::thread a(work), b(work); a.join(); b.join();\n    std::cout << count << "\\n";'),'2000\n',
     ('Perform 500 protected increments in each worker.', 'i < 1000', 'i < 500', '1000\n', 'Both workers update the same int under the same mutex, and main reads only after joining both.'),
     'What must use the locking discipline?', 'Every conflicting access to the protected state', ['Only writes in the first thread','Only the final print'], 'An unlocked conflicting access can still produce a data race.', 'thread.mutex', C)
unit(S,'condition-variables','Wait on a predicate, not a notification count',14,
     'A condition variable coordinates waiting for shared state. The predicate is checked under the associated mutex, and wait releases and reacquires the lock around blocking.|Notifications can be missed before waiting and waits can wake spuriously. A predicate loop handles both by checking the actual condition rather than assuming one notification means one item.|Shutdown must change the predicate and notify affected waiters. Destroying shared state while a waiter still references it violates the lifetime contract.',
     program('thread mutex condition_variable', '    std::mutex m; std::condition_variable cv; bool ready = false; int value = 0;\n    std::thread worker([&] { std::unique_lock<std::mutex> lock(m); cv.wait(lock, [&] { return ready; }); value = 7; });\n    { std::lock_guard<std::mutex> lock(m); ready = true; }\n    cv.notify_one(); worker.join();\n    std::cout << value << "\\n";'),'7\n',
     ('Publish a value as part of the protected ready transition.', [('ready = true;', 'value = 9; ready = true;'), ('value = 7;', 'value += 1;')], '', '10\n', 'The producer stores the payload before making ready true under the lock. The worker reacquires that lock before using the state.'),
     'Why use the predicate overload of wait?', 'To recheck shared state after missed or spurious notifications', ['To guarantee exactly one wakeup','To avoid locking the predicate state'], 'The predicate is the truth; a notification is only a wakeup opportunity.', 'thread.condition', C)
unit(S,'deadlock-avoidance','Acquire related locks with a single policy',17,
     'Two threads can deadlock if each holds a mutex the other needs. A consistent global order or a suitable multi-lock operation can prevent this particular cycle.|scoped_lock can acquire multiple mutexes using deadlock-avoidance behavior under its requirements, then release them with RAII. Do not pass the same nonrecursive mutex twice.|Deadlock freedom is broader than mutex acquisition. Joining a worker that waits on the joining thread or invoking callbacks under locks can create other cycles.',
     program('mutex', '    std::mutex a, b; int left = 3, right = 7;\n    { std::scoped_lock lock(a, b); std::swap(left, right); }\n    std::cout << left << " " << right << "\\n";'),'7 3\n',
     ('Transfer two units while holding both locks instead of swapping.', 'std::swap(left, right);', 'left += 2; right -= 2;', '5 5\n', 'The related update happens under both mutexes. The example assumes the transfer is within each account domain and does not replace input validation.'),
     'Can scoped_lock solve every possible program deadlock?', 'No; other wait and ownership cycles remain possible', ['Yes','Only if the mutexes have different names'], 'Its multi-lock algorithm addresses lock acquisition, not arbitrary dependency cycles.', 'thread.lock.scoped', C)
unit(S,'futures','Futures transport a result or exception',14,
     'A future observes shared asynchronous result state. get consumes an ordinary future result and rethrows a stored exception; a future is not a general thread-lifetime or cancellation abstraction.|std::async has launch policies with materially different execution behavior. Request launch::async when actual asynchronous launch is part of the example contract.|Destruction and waiting behavior can depend on how the shared state was created. Avoid holding locks across operations that may wait for a task that needs those locks.',
     program('future', '    auto answer = std::async(std::launch::async, [] { return 6 * 7; });\n    std::cout << answer.get() << "\\n";'),'42\n',
     ('Transport an exception and handle it at get().', [('return 6 * 7;', 'throw std::runtime_error("failure"); return 0;'), ('std::cout << answer.get() << "\\n";', 'try { (void)answer.get(); } catch (const std::runtime_error&) { std::cout << "caught\\n"; }')], '', 'caught\n', 'The task exception is captured in the shared state. get rethrows it on the consuming thread.'),
     'Where does an exception from this async function become observable?', 'At get(), through the future shared state', ['Only in a debugger','It is always discarded'], 'The future communicates both normal completion and stored failure.', 'futures', C)
unit(S,'atomic-counters','Atomicity is narrower than an application invariant',14,
     'An atomic operation prevents a data race on that atomic object under its rules. It does not make a sequence of operations on several objects one transaction.|A relaxed fetch_add can count independent events when only the final count after thread joins matters. It does not publish unrelated non-atomic payloads.|Choose memory ordering from a happens-before argument, not from a benchmark alone. Stronger ordering also does not automatically fix a broken multi-object protocol.',
     program('thread atomic', '    std::atomic<int> count{0};\n    auto work = [&] { for (int i = 0; i < 1000; ++i) count.fetch_add(1, std::memory_order_relaxed); };\n    std::thread a(work), b(work); a.join(); b.join();\n    std::cout << count.load() << "\\n";'),'2000\n',
     ('Count three workers with the same relaxed counter.', 'std::thread a(work), b(work); a.join(); b.join();', 'std::thread a(work), b(work), c(work); a.join(); b.join(); c.join();', '3000\n', 'The count operations remain atomic and joins establish completion before the final observation. No unrelated payload is being published by the counter.'),
     'Does relaxed fetch_add publish unrelated non-atomic data?', 'Not by itself', ['Always','Only when the increment is one'], 'Atomic modification and inter-object synchronization are different properties.', 'atomics.order', C)
unit(S,'release-acquire','Publication requires a matching synchronization edge',14,
     'A release operation can publish preceding writes to a thread whose acquire operation reads from the relevant release sequence under the memory-model rules. The matching relation is essential.|A typical one-shot publication writes a payload, then stores a ready flag with release; the consumer waits with acquire before reading the payload.|This does not automatically support resetting and reusing the same payload concurrently. Multiple producers, generations, reclamation, and cancellation need their own protocol.',
     program('atomic thread', '    int payload = 0; std::atomic<bool> ready{false};\n    std::thread producer([&] { payload = 7; ready.store(true, std::memory_order_release); });\n    while (!ready.load(std::memory_order_acquire)) std::this_thread::yield();\n    std::cout << payload << "\\n"; producer.join();'),'7\n',
     ('Publish a different immutable payload with the same one-shot protocol.', 'payload = 7;', 'payload = 11;', '11\n', 'The acquire observation precedes reading the producer-written payload. Keep the one-shot lifetime and synchronization assumptions explicit.'),
     'What makes the ordinary payload read safe here?', 'The matching release/acquire publication before the read', ['The flag is merely volatile','yield() is a memory barrier for all data'], 'Volatile and yielding do not establish the required C++ synchronization relation.', 'atomics.order', C)
unit(S,'atomic-wait','Waiting atomics still require a state protocol',20,
     'atomic::wait waits while the atomic value equals an expected value, subject to its specified behavior. notify_one and notify_all wake eligible waiters but do not replace changing the state.|A producer should store the new state with an appropriate order and notify waiters. A consumer must recheck the state and use ordering that supports any payload it then reads.|Repeated value changes can introduce ABA-style observations. A monotonic generation counter or another protocol may be necessary when every transition matters.',
     program('atomic thread', '    std::atomic<int> state{0};\n    std::thread producer([&] { state.store(1, std::memory_order_release); state.notify_one(); });\n    state.wait(0, std::memory_order_acquire);\n    std::cout << state.load() << "\\n"; producer.join();'),'1\n',
     ('Publish state two while still waiting for the initial zero to change.', 'state.store(1,', 'state.store(2,', '2\n', 'The waiter compares with zero and can proceed when it observes the different published state. notify without a state change would not establish this condition.'),
     'Does notify alone change the atomic value?', 'No', ['Yes, it increments it','Only for atomic<int>'], 'State transitions and wakeups are separate operations.', 'atomics.wait', C)
unit(S,'stop-callbacks','A cancellation callback has a bounded lifetime',20,
     'stop_callback registers an operation to be invoked when its associated stop state receives a request. If stop was already requested, registration can invoke it immediately.|The callback registration lifetime and callback execution synchronization matter for teardown. Keep the callback short and avoid blocking cycles involving the thread that owns registration.|The callback must not access destroyed captured state. Arrange declarations so registrations are destroyed before the dependencies they borrow.',
     program('stop_token', '    int calls = 0; std::stop_source source;\n    { std::stop_callback callback(source.get_token(), [&] { ++calls; }); source.request_stop(); source.request_stop(); }\n    std::cout << calls << "\\n";'),'1\n',
     ('Request stop before registering the callback.', [('std::stop_source source;', 'std::stop_source source; source.request_stop();'), ('source.request_stop(); source.request_stop();', '/* already requested */')], '', '1\n', 'The callback executes during registration because stop is already requested. Repeated requests do not invoke one registration repeatedly.'),
     'Can registration invoke a stop callback immediately?', 'Yes, when stop has already been requested', ['No, it always waits for another thread','Only after the registration is destroyed'], 'Registration must account for the current stop-state value.', 'stoptoken', C)
unit(S,'latches-and-barriers','One-shot readiness differs from repeated phases',20,
     'A latch counts down toward a one-time release; it cannot be reset. A barrier coordinates repeated phases with a completion step under its contract.|Choose a primitive from the protocol rather than manually combining unrelated flags. Every participant must eventually fulfill its arrival or drop responsibility.|A missing arrival can block all other participants. Exception and cancellation paths need a design that prevents abandoned responsibilities.',
     program('latch thread', '    std::latch done(2);\n    std::thread a([&] { done.count_down(); });\n    std::thread b([&] { done.count_down(); });\n    done.wait(); a.join(); b.join();\n    std::cout << "ready\\n";'),'ready\n',
     ('Use a single participant and the corresponding initial count.', [('done(2)', 'done(1)'), ('std::thread b([&] { done.count_down(); });', ''), ('a.join(); b.join();', 'a.join();')], '', 'ready\n', 'The initial count now matches the number of participants. Waiting does not replace joining the worker handle.'),
     'Can a latch be reset for the next phase?', 'No; use a suitable repeated-phase primitive', ['Yes, by waiting twice','Only if every worker joins'], 'A latch is a one-shot synchronization object.', 'thread.latch', C)
unit(S,'coroutine-model','A coroutine frame needs one destruction owner',20,
     'A coroutine can suspend and later resume while its frame retains state. The promise type and awaiter protocol determine how calls, suspension, yielded values, exceptions, and final completion are exposed.|A coroutine_handle is a non-owning handle-like capability unless a wrapper supplies ownership. Destroying a live frame twice, resuming after completion, or retaining references past their owners violates the protocol.|The project in this stage implements a move-only generator that owns its handle and destroys the frame exactly once. Cancellation of an asynchronous operation additionally needs to coordinate pending callbacks and frame lifetime.',
     program('coroutine', '    std::cout << std::suspend_always{}.await_ready() << " " << std::suspend_never{}.await_ready() << "\\n";'),'0 1\n',
     ('Inspect two always-suspend awaiters instead.', 'std::suspend_never{}', 'std::suspend_always{}', '0 0\n', 'await_ready=false means this awaiter does not bypass suspension through immediate readiness. The complete protocol also includes await_suspend and await_resume.'),
     'Does a bare coroutine_handle automatically destroy its frame on scope exit?', 'No; an owning wrapper must define destruction', ['Yes','Only for generators'], 'Ownership and the coroutine protocol must be implemented deliberately.', 'dcl.fct.def.coroutine', [])

S='09 Toolchains, evolution, and expert boundaries'
unit(S,'odr-and-linkage','A declaration is not a missing definition',14,
     'Separate translation units can share declarations through headers. A declaration tells the compiler about an entity; a definition supplies the entity subject to linkage and one-definition rules.|Header guards or pragma once prevent repeated inclusion within a translation unit. They do not generally permit multiple non-inline external definitions across a linked program.|Put a non-inline function definition in one implementation file and share its declaration, or use an appropriately inline definition. Templates and inline entities have their own cross-translation-unit requirements.',
     program('', '    std::cout << twice(7) << "\\n";', 'int twice(int);\nint twice(int n) { return n * 2; }\n'),'14\n',
     ('Use an inline definition suitable for a shared header under its ODR requirements.', 'int twice(int);\nint twice(int n)', 'inline int twice(int n)', '14\n', 'inline permits specified repeated definitions across translation units, provided the ODR requirements such as corresponding definitions are satisfied. It does not require machine-code inlining.'),
     'Do header guards alone solve duplicate external definitions across translation units?', 'No', ['Yes','Only when the header extension is hpp'], 'Guards affect preprocessing within each translation unit, while the ODR governs the linked program.', 'basic.def.odr')
unit(S,'c-linkage','Language linkage is an ABI boundary',14,
     'extern "C" specifies C language linkage where permitted. It is useful for C-compatible interfaces, but does not automatically make arbitrary C++ class layouts or exception behavior usable from C.|Keep the boundary in simple explicitly specified data types and ownership operations. Pair allocation and deallocation in the implementation that owns the resource contract.|Do not let C++ exceptions cross a boundary whose caller cannot handle the C++ unwinding contract. Translate failures to an explicit status and preserve output ownership on failure.',
     program('', '    std::cout << add_values(2, 3) << "\\n";', 'extern "C" int add_values(int a, int b) { return a + b; }\n'),'5\n',
     ('Call the boundary with signed operands whose sum stays in range.', 'add_values(2, 3)', 'add_values(-4, 7)', '3\n', 'The same C-linkage function is called from this C++ translation unit. This check does not establish binary compatibility with every C compiler or calling convention.'),
     'Does extern "C" make every C++ class a portable C ABI type?', 'No', ['Yes','Only if the class is public'], 'Language linkage and data-layout/ownership compatibility are different contracts.', 'dcl.link')
unit(S,'compile-diagnostics','Repair the rejected lifetime contract',14,
     'A compiler rejection can reveal that an interface cannot satisfy its declared type contract. An int& result must refer to a suitable live object; a temporary integer cannot initialize a non-const lvalue reference.|Returning a value is appropriate when a function computes an independent small result. Returning a reference requires an owner whose lifetime and mutation policy the caller can rely on.|The displayed base example is intentionally ill-formed and belongs in an expected-diagnostic check. A warning about a dangling const reference would require separate scrutiny even if compilation succeeded.',
     program('', '    std::cout << broken() << "\\n";', 'int& broken() { return 42; }\n'),'',
     ('Repair the function by returning an independent value.', 'int& broken()', 'int broken()', '42\n', 'An int result owns its value at the call site and does not refer to the destroyed temporary.'),
     'What is the appropriate result type for this computed integer?', 'int by value', ['int& bound to the temporary','A raw pointer to the local temporary'], 'Value return avoids an invalid borrowed lifetime.', 'dcl.init.ref')
UNITS[-1]['expectedDiagnostic'] = 'non-const lvalue reference'
unit(S,'performance-contracts','Measure the intended workload and verify the result',14,
     'Algorithmic complexity models growth; measurement captures a particular implementation, machine, and workload. Both matter when choosing a data structure or optimization.|Prevent a benchmark from measuring dead code, setup work, or an invalid result. Use representative sizes, repeated trials, appropriate clocks, and a correctness oracle.|One fast sample is not a universal performance claim. Record compiler options, hardware, inputs, variability, and whether sanitizers or debug checks changed the workload.',
     program('algorithm vector', '    std::vector<int> values{1, 3, 5, 7};\n    std::cout << std::binary_search(values.begin(), values.end(), 5) << "\\n";'),'1\n',
     ('Check a value absent from the same sorted input.', 'values.end(), 5)', 'values.end(), 6)', '0\n', 'The sorted precondition holds in both cases. An optimization is useful only when its required ordering and returned result remain correct.'),
     'What must be checked before trusting a faster implementation?', 'That it computes the required result under the intended workload', ['Only its shortest recorded time','Only that it allocates less'], 'Timing a wrong or optimized-away computation does not validate an improvement.', 'alg.binary.search', [])
unit(S,'alignment-and-allocation','Storage alignment is a type requirement',17,
     'An object requires storage with sufficient size and alignment. Aligning bytes does not by itself start an arbitrary object lifetime; construction and destruction remain separate operations.|Over-aligned allocations have language and library support under their rules. Prefer standard owning containers and allocators to manual address arithmetic when possible.|Pair the allocation and deallocation forms correctly. Mixing delete[], delete, free, and foreign release functions can invalidate an otherwise plausible ownership design.',
     program('memory', '    auto value = std::make_unique<Block>();\n    std::cout << (alignof(Block) >= 64) << " " << value->number << "\\n";', 'struct alignas(64) Block { int number = 7; };\n'),'1 7\n',
     ('Change the value while preserving the over-aligned owner.', 'int number = 7;', 'int number = 9;', '1 9\n', 'make_unique uses the allocation and destruction path appropriate for Block. The check states an alignment property rather than assuming an absolute address.'),
     'Does obtaining aligned storage alone construct every object in it?', 'No', ['Yes','Only when the alignment exceeds eight'], 'Storage allocation and object lifetime establishment are separate steps.', 'basic.align')
unit(S,'cpp14-evolution','C++14 enables generic lambdas and init-captures',14,
     'Use C++14 as the minimum course baseline while still teaching the earlier facilities that remain part of it. Generic lambda parameters, init-captures, relaxed constexpr rules, and make_unique are important additions at this boundary.|A generic lambda has a templated call operator. Each selected argument type must support the body expressions, just like an ordinary function template instantiation.|A minimum-standard label is a compatibility requirement, not a claim that every compiler extension in the example belongs to that standard. Validate strict language modes.',
     program('', '    auto twice = [](auto x) { return x + x; };\n    std::cout << twice(3) << " " << twice(2.5) << "\\n";'),'6 5\n',
     ('Capture an offset with a C++14 init-capture.', '[](auto x) { return x + x; }', '[offset = 1](auto x) { return x + x + offset; }', '7 6\n', 'The closure owns the initialized offset and deduces each call argument type independently.'),
     'Which selected baseline supports generic lambda parameters?', 'C++14', ['Only C++26','No C++ standard supports them'], 'Generic lambdas are a C++14 addition.', 'expr.prim.lambda')
unit(S,'cpp17-evolution','C++17 combines branch selection and value vocabulary',17,
     'C++17 adds facilities including if constexpr, structured bindings, class-template argument deduction, fold expressions, inline variables, and library vocabulary types. Study the interaction rather than memorizing a year list.|if constexpr discards a branch according to a constant condition under its template rules. It does not make arbitrary nondependent invalid code legal everywhere.|Use version comparisons to explain migration constraints. Some changes affect semantics, not just syntax, including guaranteed copy-elision cases and evaluation-order rules.',
     program('type_traits', '    std::cout << describe(7) << " " << describe(2.5) << "\\n";', 'template<class T> const char* describe(T) { if constexpr (std::is_integral_v<T>) return "integral"; else return "other"; }\n'),'integral other\n',
     ('Exercise deduction with a boolean integral type.', 'describe(7)', 'describe(true)', 'integral other\n', 'bool is an integral type under is_integral. The selected constexpr branch follows the type trait, not the value magnitude.'),
     'Does if constexpr unconditionally legalize invalid code outside templates?', 'No', ['Yes','Only if the condition is false'], 'Discarded-statement rules have specific contexts and do not erase all semantic checking.', 'stmt.if')
unit(S,'cpp20-evolution','C++20 requires coordinated compiler and library support',20,
     'C++20 introduces concepts, ranges, coroutines, modules, three-way comparison, designated initializers, and expanded constant-evaluation tools, alongside library changes. Their implementations can mature at different rates.|Designated initializers for aggregates follow declaration order in C++. Do not import a C designated-initializer pattern without checking the C++ rules.|Modules need a build graph and compiler workflow for module artifacts. Accepting the c++20 flag alone does not establish a working modules build or every new library feature.',
     program('', '    Options options{.width = 3, .height = 4};\n    std::cout << options.width * options.height << "\\n";', 'struct Options { int width; int height; };\n'),'12\n',
     ('Use a square configuration while keeping declaration-order initialization.', 'options{.width = 3, .height = 4}', 'options{.width = 5, .height = 5}', '25\n', 'The aggregate members are designated in declaration order. These initializers do not call a custom validating constructor.'),
     'Do C++ designated initializers freely reorder members like every C example?', 'No; C++ imposes its own declaration-order rules', ['Yes','Only when the members have equal types'], 'Cross-language syntax similarities do not imply identical rules.', 'dcl.init.aggr')
unit(S,'cpp23-evolution','C++23 extends both language syntax and library APIs',23,
     'C++23 adds language facilities such as if consteval, explicit object parameters, multidimensional subscripting, and other targeted changes. Library additions include expected, mdspan, print facilities, and new ranges tools with per-implementation support.|if consteval selects based on whether evaluation occurs in a manifestly constant-evaluated context. It is not a runtime test of whether an optimizer happened to fold an expression.|Keep required language and library features in the example metadata. A compiler version without a matching library implementation may support only part of the lesson.',
     program('', '    constexpr int compile_time = mode();\n    int runtime = mode();\n    std::cout << compile_time << " " << runtime << "\\n";', 'constexpr int mode() { if consteval { return 1; } else { return 2; } }\n'),'1 2\n',
     ('Require both calls in constant-expression initializers.', 'int runtime = mode();', 'constexpr int runtime = mode();', '1 1\n', 'Both initializers now require constant evaluation. This is a language-context distinction, not an optimization-level measurement.'),
     'Does if consteval test whether the optimizer folded a runtime call?', 'No; it concerns the language constant-evaluation context', ['Yes','Only in release builds'], 'Manifest constant evaluation differs from optional optimization.', 'stmt.if')


def reference(key, title, prose, prompt, answer, question, correct, wrong, anchor, standard=26):
    unit(S, key, title, standard, prose, '', '', (prompt, '', '', '', answer), question, correct, wrong, answer, anchor,
         [] if standard != 26 else [])
    UNITS[-1]['referenceOnly'] = True


reference('modules','Modules change visibility and build dependencies',
          'A named module can export an interface and hide implementation details. Importing a module is distinct from textual header inclusion, and module units still obey linkage and definition rules.|Build the module interface before its importers using the compiler-specific module artifact workflow. Record the exact compiler and flags; binary module artifacts are not generally portable across unrelated builds.|This unit is a design exercise. It does not claim that the single-file mobile gateway or a CMake configuration without a dependency scanner builds module projects.',
          'Design the build graph for a module interface exporting a sum function and two importing translation units. Explain where its implementation belongs.',
          'Compile the interface first to the implementation-specific module artifact and object as required. Compile both importers against the matching interface artifact, then link their objects with the module implementation object. Keep unexported implementation details out of the importer contract and rebuild dependent artifacts when the interface or toolchain changes.',
          'Can the single-file runner contract represent a complete multi-unit module build?', 'No', ['Yes, import creates every missing source file','Only if the source filename ends in cpp'], 'module', 20)
reference('reflection26','C++26 reflection needs a versioned metaprogramming contract',
          'Reflection facilities expose compile-time information for metaprogramming under the adopted specification. Distinguish an adopted facility from an unrelated proposal with similar syntax.|A serializer generator must still define which members are public API, how private data is treated, and how names and versioning affect compatibility. Automatic enumeration is not an external schema policy.|This is reference-only practice. The local Apple Clang 21 check does not validate reflection support; compiler branches, feature macros, and required flags must be recorded before an executable example is marked verified.',
          'Propose a reflection-driven serializer contract that excludes credentials and preserves compatibility when a member is renamed.',
          'Use an explicit allowlist or opt-in metadata for serialized members, stable external field identifiers separate from source names, and a versioned decoding policy. Reject or deliberately migrate incompatible schema changes. Test that excluded fields never enter output and that old fixtures remain decodable.',
          'Does member reflection automatically define a safe persistent schema?', 'No', ['Yes, member names are always stable','Only when optimization is enabled'], 'meta')
reference('contracts26','Contracts express obligations with specified evaluation semantics',
          'C++26 contract facilities distinguish program obligations from ordinary recoverable input parsing. The exact adopted semantics and supported implementation modes must be checked against WG21 and the chosen compiler.|A function that requires a valid index still needs a separate policy for untrusted external input. Contract checks must not be the sole defense when the deployment configuration may not evaluate them as assumed.|This is reference-only practice. Do not silently substitute assert, exceptions, or a proposal-era syntax and call it a verified implementation of the adopted contract facility.',
          'Separate the obligations of a trusted indexing helper from the validation of a network-provided index.',
          'Validate and bound the external integer before calling the trusted helper. Document the helper precondition and the selected contract evaluation behavior. Ensure checked parsing remains effective independently of optional diagnostic checks, and test invalid external values without invoking undefined access.',
          'Should optional diagnostic evaluation replace validation of untrusted input?', 'No', ['Always','Only for positive integers'], 'basic.contract')
reference('execution26','Sender/receiver operations own completion and cancellation state',
          'Execution facilities compose asynchronous operations around an explicit completion protocol. A sender description, a connected operation state, and actual starting/completion are distinct concepts.|The operation state and resources borrowed by callbacks must live until the completion protocol permits release. Cancellation is a request with specified observation behavior, not proof that every operation has already stopped.|This unit is reference-only. Check the adopted library specification, feature macros, scheduler backend, and actual toolchain before labelling a sender example runnable.',
          'Describe ownership for a composed asynchronous read and parse operation that can complete, fail, or stop.',
          'Give one enclosing owner the connected operation state and its input buffer through terminal completion. Route value, error, and stopped completions through one run identity and finalize exactly once. Request cancellation through the documented stop channel and defer resource release until the operation can no longer access them.',
          'Does requesting stop prove every asynchronous callback has already finished?', 'No', ['Yes','Only if a stop token exists'], 'exec')
reference('inplace-vector26','Fixed-capacity growth still constructs and destroys elements',
          'A fixed-capacity vector-style facility stores a bounded sequence without ordinary dynamic capacity growth under its specified contract. Capacity and the number of live elements remain different concepts.|Insertion into a full sequence needs the exact documented failure behavior. Element construction can still fail even when storage allocation is unnecessary, and element types can themselves own heap resources.|This is reference-only C++26 practice. Do not claim that inline storage establishes universal allocation freedom or that a homegrown ring is a conforming implementation of the standard container.',
          'Specify failure and ownership tests for appending a move-only resource to a full bounded sequence.',
          'Check the facility-specific full-capacity behavior without invoking an operation outside its preconditions. Track whether the incoming owner remains valid or was consumed according to that API. Verify destruction counts after successful insertion, removal, failed construction, and container teardown, including a zero-capacity case when supported.',
          'Does inline container storage prevent element-owned allocations?', 'No', ['Always','Only for non-copyable elements'], 'inplace.vector')
reference('simd26','Data parallelism needs a lane and remainder policy',
          'SIMD facilities express operations over multiple lanes. Correctness still depends on element types, alignment/access contracts, masks, and treatment of inputs that do not fill the final group.|Vectorizing floating arithmetic can change intermediate grouping and observable rounding. A scalar reference and a justified numerical comparison make the intended accuracy visible.|This is reference-only practice. Record adopted API names and actual compiler/library/target support before presenting a runnable SIMD program; instruction-set marketing alone is not validation.',
          'Design tests for vectorizing a sum over an arbitrary-length input without reading beyond the range.',
          'Compare with a scalar reference on empty input, shorter-than-one-group input, exact group multiples, and remainders. Process the tail using a specified masked or scalar path and obey load alignment requirements. Use exact comparison for bounded integer arithmetic or a justified error budget for floating results.',
          'Can a vectorized load read past the valid range just because unused lanes are ignored later?', 'No', ['Yes','Only on aligned arrays'], 'simd')

# Headers used by worked solutions are explicit rather than relying on transitive includes.
for entry in UNITS:
    for name in ('string', 'stdexcept', 'utility'):
        tokens = {'string': ['std::string'], 'stdexcept': ['std::runtime_error'], 'utility': ['std::swap']}[name]
        if any(token in entry['code'] + entry['solution'] for token in tokens):
            for field in ('code', 'solution'):
                if entry[field] and '#include <'+name+'>' not in entry[field]:
                    entry[field] = '#include <'+name+'>\n' + entry[field]
